exports.hrattendancereport = async (req, res, next) => {
  try {
    let = {
      companyMasterID,
      YearMM,
      limit,
      page,
      searchQuery,
      department,
      designation1,
      branchMasterID,
    } = req.body;
    if (
      department.length > 0 &&
      designation1.length > 0 &&
      branchMasterID.length > 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE departmentid IN (` +
          department.join(',') +
          `) AND designationid IN (` +
          designation.join(',') +
          `) AND branchid IN (` +
          branchMasterID.join(',') +
          `)`
      );
    } else if (
      department.length > 0 &&
      designation1.length <= 0 &&
      branchMasterID.length <= 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE departmentid IN (` +
          department.join(',') +
          ` )`
      );
    } else if (
      department.length <= 0 &&
      designation1.length > 0 &&
      branchMasterID.length <= 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE designationid IN (` +
          designation1.join(',') +
          `)`
      );
    } else if (
      department.length <= 0 &&
      designation1.length <= 0 &&
      branchMasterID.length > 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE branchid IN (` +
          branchMasterID.join(',') +
          `)`
      );
    } else if (
      department.length <= 0 &&
      designation1.length > 0 &&
      branchMasterID.length > 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE branchid IN (` +
          branchMasterID.join(',') +
          `) && designationid IN (` +
          designation.join(',') +
          `)`
      );
    } else if (
      department.length > 0 &&
      designation1.length <= 0 &&
      branchMasterID.length > 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE branchid IN (` +
          branchMasterID.join(',') +
          `) && departmentid IN (` +
          department.join(',') +
          `)`
      );
    } else if (
      department.length > 0 &&
      designation1.length > 0 &&
      branchMasterID.length <= 0
    ) {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `) WHERE designationid IN (` +
          designation.join(',') +
          `) && departmentid IN (` +
          department.join(',') +
          `)`
      );
    } else {
      results = await executeQuery(
        `select * from public.ms_fun_rpt_hr_attn_tran(` +
          companyMasterID +
          `,` +
          YearMM +
          `)`
      );
    }
    var finalresp = [];
    if (results != undefined && results.length != 0) {
      results.sort(
        (a, b) => parseInt(a.usermasterid) - parseInt(b.usermasterid)
      );
      var unique = [],
        uid;

      results.forEach((element) => {
        if (uid != element.usermasterid) {
          unique.push(element);
          uid = element.usermasterid;
        }
      });

      unique.forEach((element) => {
        let empdata = results.filter(
          (r1) => r1.usermasterid == element.usermasterid
        );
        empdata.sort((e1, e2) => e1.sortindex - e2.sortindex);
        if (empdata.length != 0) {
          let leavename = [];
          empdata.forEach((element) => {
            let arr = [];
            for (var key in element) {
              if (key == 'leavename') {
                arr.push(element[key]);
              }
              if (key == 'vn_field_val') {
                arr.push(element[key]);
              }
              if (arr.length == 2) {
                leavename.push({
                  ltype: arr[1],
                  side: arr[0],
                });
                arr = [];
              }
            }
          });

          var newJson = {
            EmployeeName: empdata[0].employeename,
            MonthDays: empdata[0].gender,
            MonthWorkingDays: empdata[0].dob,
            YearMonth: empdata[0].yearmon,
            Designation: empdata[0].designationname,
            Department: empdata[0].departmentname,
            Branch: empdata[0].branchname,
          };

          leavename.forEach((el, ind) => {
            el.val = el.ltype;
            let key = el.side;
            newJson[key] = el.val;
          });

          finalresp.push(newJson);
        }
      });
    } else {
    }

    res
      .status(200)
      .json({ status: 200, data: finalresp, totalcount: finalresp.length });
  } catch (err) {
    if (!err.statusCode) {
      res.status(200).json({ status: 401, message: err.message, data: {} });
    }
    next(err);
  }
};

