exports.tracking_report = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      userMasterID,
      enddate,
      startdate,
      page,
      limit,
      exportData,
    } = req.body;

    if (!startdate || !enddate || new Date(startdate) > new Date(enddate))
      return res
        .status(200)
        .json({ status: 401, message: 'Please pass valid date range' });

    const condition = {};
    if (companyMasterID) condition.companyMasterId = companyMasterID;
    if (userMasterID && userMasterID.length != 0)
      condition.userMasterID = userMasterID;
    condition.status = 1;

    const paginationQuery = {};
    if (page && limit && !exportData) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = limit;
    }

    const allUser = await UserMaster.findAndCountAll({
      where: condition,
      raw: true,
      ...paginationQuery,
      attributes: ['userMasterID', 'displayName', 'userNumber'],
      ...accessibleUsers(req.userDetails, false),
      include: {
        model: EmployeeJoiningDetails,
        attributes: ['employeeCode'],
      },
    });
    const data = [];

    for (const item of allUser.rows) {
      const datesArray = [];
      for (
        let j = new Date(startdate);
        j <= new Date(enddate);
        j.setDate(j.getDate() + 1)
      ) {
        const tempData = { date: j.toISOString().slice(0, 10), total_kms: 0.0 };
        datesArray.push(tempData);
      }

      const [userDepartment, userDesignation, userBranch] = await Promise.all([
        employeeDepartment(item.userMasterID, startdate),
        employeeDesignation(item.userMasterID, startdate),
        employeeBranch(item.userMasterID, startdate),
      ]);

      const userData = {
        employeeCode: item ? item['employeeJoiningDetails.employeeCode'] : '',
        userMasterID: item.userMasterID,
        user: item.displayName,
        Number: item.userNumber,
        branch: userBranch ? userBranch['branchMaster.branchName'] : '',
        department: userDepartment
          ? userDepartment['department.departmentName']
          : '',
        designation: userDesignation
          ? userDesignation['designation.designationName']
          : '',
      };

      if (!exportData) {
        userData.total_kms = datesArray;
        for (const date of userData.total_kms) {
          const findTrackingData = await TrackingKM.findOne({
            where: { userMasterID: item.userMasterID, date: date.date },
            raw: true,
            attributes: ['kilometer'],
          });
          if (findTrackingData) date.total_kms = findTrackingData.kilometer;
        }
      } else {
        for (const date of datesArray) {
          const findTrackingData = await TrackingKM.findOne({
            where: { userMasterID: item.userMasterID, date: date.date },
            raw: true,
            attributes: ['kilometer'],
          });
          userData[date.date.split('-').reverse().join('-')] = findTrackingData
            ? findTrackingData.kilometer
            : 0;
        }
      }

      data.push(userData);
    }

    if (exportData) {
      for (var item of data) delete item.userMasterID;
      await generateExcel(data, 'KM-Report', 'xlsx', res);
      return;
    }

    return res
      .status(200)
      .json({ status: 200, data: data, totalcount: allUser.count });
  } catch (err) {
    console.error(err);
    next(err);
  }
};

