exports.esic = async (req, res, next) => {
  try {
    let {
      companyMasterID,
      YYYYMM,
      page,
      limit,
      branchMasterID,
      exportData,
      exportPdf,
      exportChallan,
    } = await req.body;
    let branchID = branchMasterID;
    let finaldata = [];

    let totalcount = 0,
      companyregister,
      companydata;

    const year = YYYYMM.slice(0, 4);
    const month = YYYYMM.slice(4, 6);

    const monthdays = daysInMonth(month, year);

    const endDate = year + '-' + month + '-' + monthdays;

    const paginateCondition =
      !exportData && !exportPdf && !exportChallan && page && limit
        ? { offset: (page - 1) * limit, limit }
        : {};

    const { rows: finalUserList, count } =
      await HrSalaryTransaction.findAndCountAll({
        where: {
          salaryYYYYMM: YYYYMM,
        },
        ...paginateCondition,
        include: [
          {
            required: true,
            model: HrSalaryMaster,
            attributes: [],
            include: [
              {
                required: true,
                model: GradeSalaryStructure,
                include: [
                  {
                    required: true,
                    model: HRSalaryFields,
                    where: { payheadMasterId: 13, status: 1 },
                    attributes: [],
                  },
                ],
                attributes: [],
              },
            ],
          },
          {
            required: true,
            model: UserMaster,
            where: { companyMasterId: companyMasterID },
            ...accessibleUsers(req.userDetails, false, false),
            attributes: ['displayName'],
            include: [
              { model: EmployeeJoiningDetails, attributes: ['esicNumber'] },
              {
                required: branchMasterID ? true : false,
                model: EmployeeBranch,
                where: {
                  status: 1,
                  ...(branchMasterID && { branchID: branchMasterID }),
                  applicableDate: {
                    [Sequelize.Op.lte]: new Date(endDate),
                  },
                  [Sequelize.Op.or]: [
                    {
                      endDate: { [Sequelize.Op.gte]: new Date(endDate) },
                    },
                    {
                      endDate: { [Sequelize.Op.eq]: null },
                    },
                  ],
                },
                attributes: [],
              },
            ],
          },
        ],
        order: [[Sequelize.literal('"userMaster.displayName"'), 'ASC']],
      });

    for (let i = 0; i < finalUserList.length; i++) {
      let temp_object = {};
      temp_object['IP Number'] =
        finalUserList[i].userMaster.employeeJoiningDetails?.[0]?.esicNumber ||
        '';
      temp_object['IP Name'] = finalUserList[i].userMaster.displayName;
      temp_object['No Of Days for which wages paid'] = Math.ceil(
        +finalUserList[i].SalaryCalcOnDays
      );

      const salarydata = await getSalaryData(
        finalUserList[i].userMasterID,
        YYYYMM
      );

      const finalGross =
        +finalUserList[i].calculatedOn > 0
          ? +finalUserList[i].calculatedOn
          : await calculateGrossSum(salarydata);

      temp_object['Total Amount Wages'] = finalGross
        ? +finalGross.toFixed(2)
        : 0;

      temp_object['ESIC Amount'] = finalUserList[i].EmployeeSalaryAmount
        ? +finalUserList[i].EmployeeSalaryAmount.toFixed(2)
        : 0;

      salarydata.map((e) => {
        if (e.payheadMasterId == 14) {
          temp_object['esico'] = e.EmployeeSalaryAmount
            ? +e.EmployeeSalaryAmount.toFixed(2)
            : 0;
        }
      });

      finaldata.push(temp_object);
    }

    if (companyMasterID) {
      let esicno = await executeQuery(
        `SELECT "ESINo" FROM "companyRegisters" where "companyMasterId"=` +
          companyMasterID +
          ``
      );
      if (esicno.length > 0) {
        companyregister = {
          esicno: esicno[0].ESINo != undefined ? esicno[0].ESINo : '',
        };
      } else {
        companyregister = {
          esicno: '',
        };
      }

      companydata = await companyMasters.findOne({
        where: { companyMasterID: companyMasterID },
        raw: true,
      });
    }

    let branchData;
    if (branchMasterID) {
      branchData = await BranchMaster.findOne({
        where: {
          branchMasterID: branchMasterID,
        },
        attributes: ['branchAddress'],
      });
    }

    if (exportData) {
      const finalDataExcel = [];

      let esicTotal = 0;
      let esiccoTotal = 0;
      let TotalWages = 0;

      for (let i = 0; i < finaldata.length; i++) {
        // var logdatetime = this.formatDate(new Date(this.export[i].logDateTime));

        const data1 = {
          ['IP Number']: finaldata[i]['IP Number'],
          ['IP NAME']: finaldata[i]['IP Name'],
          ['No of Days for which wages paid/payable during the month']:
            finaldata[i]['No Of Days for which wages paid'],
          ['Total Monthly Wages']: finaldata[i]['Total Amount Wages'],
          ['ESIC Amount (0.75%)']: finaldata[i]['ESIC Amount'],
          ['ESIC Amount (3.25%)']: finaldata[i]['esico'],
          ['Reason Code for Zero workings days(numeric only: provide 0 for all other reasns: Click on the link for reference)']:
            '',
          ['Last working day (Format DD/MM/YYYY or DD-MM-YYYY)']: '',
        };

        esicTotal = esicTotal + Number(finaldata[i]['ESIC Amount']);
        esiccoTotal = esiccoTotal + Number(finaldata[i]['esico']);
        TotalWages = TotalWages + Number(finaldata[i]['Total Amount Wages']);

        finalDataExcel.push(data1);
      }

      let temp = {};
      finalDataExcel.push(temp);
      finalDataExcel.push(temp);

      temp = {
        ['IP Number']: 'TOTAL',
        ['IP NAME']: '',
        ['No of Days for which wages paid/payable during the month']: '',
        ['Total Monthly Wages']: TotalWages,
        ['ESIC Amount (0.75%)']: esicTotal,
        ['ESIC Amount (3.25%)']: esiccoTotal,
        ['Reason Code for Zero workings days(numeric only: provide 0 for all other reasns: Click on the link for reference)']:
          '',
        ['Last working day (Format DD/MM/YYYY or DD-MM-YYYY)']: '',
      };
      finalDataExcel.push(temp);

      await generateExcel(finalDataExcel, 'ESIC', 'xlsx', res);
      return;
    }

    if (exportPdf) {
      const companyDetails = companydata;

      const { companyName, companyAddress, companyLogo } = companyDetails;

      const headers = Object.keys(finaldata[0]);

      const pdfData = {
        datalength: headers.length,
        companyName,
        companyAddress: branchData?.branchAddress || companyAddress,
        companyLogo,
        headers,
        finaldata,
        ApiURL: mainApiUrl,
      };

      const getTemplate1 = (type) => {
        const file = path.join(__dirname, `../html/${type}.html`);
        return file;
      };

      Handlebars.registerHelper({
        eq: (v1, v2) => v1 === v2,
        ne: (v1, v2) => v1 !== v2,
        lt: (v1, v2) => v1 < v2,
        gt: (v1, v2) => v1 > v2,
        lte: (v1, v2) => v1 <= v2,
        gte: (v1, v2) => v1 >= v2,
        and() {
          return Array.prototype.every.call(arguments, Boolean);
        },
        or() {
          return Array.prototype.slice.call(arguments, 0, -1).some(Boolean);
        },
      });

      const readFile = (name) => {
        return new Promise((resolve, reject) => {
          fs.readFile(name, 'utf-8', (err, result) => {
            if (err) {
              reject(err);
            } else {
              resolve(result);
            }
          });
        });
      };

      const filePath = await getTemplate1('esicReport');

      const file = await readFile(filePath);
      const template = Handlebars.compile(file);
      const html = template(pdfData);

      const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox'],
      });
      const page = await browser.newPage();

      // Set the HTML content of the page
      await page.setContent(html);

      // Generate PDF
      const pdfBuffer = await page.pdf({
        format: 'A4', // Page format (A4 in this case)
        printBackground: true, // print background
        timeout: 120000,
      });
      await browser.close();

      let base64path = Buffer.from(pdfBuffer).toString('base64');

      return res.status(200).json({
        status: 200,
        data: base64path,
      });
    }

    if (exportChallan) {
      const getTemplate = (type) => {
        const file = path.join(__dirname, `../html/${type}.html`);
        return file;
      };
      const filePath = getTemplate('esicChallan');

      const readFile = (name) => {
        return new Promise((resolve, reject) => {
          fs.readFile(name, 'utf-8', (err, result) => {
            if (err) {
              reject(err);
            } else {
              resolve(result);
            }
          });
        });
      };

      let amount = 0;
      let employee = 0;
      let employers = 0;
      let totalRupees = 0;
      let finalData = finaldata;
      let companyaddress = companydata.companyAddress;
      let companyname = companydata.companyName;
      let codeNo = companyregister.esicno;
      let NoEmployee = finaldata.length;

      for (let i = 0; i < finalData.length; i++) {
        amount = amount + Number(finalData[i]['Total Amount Wages']);
        employee = employee + Number(finalData[i]['ESIC Amount']);
        employers = employers + Number(finalData[i]['esico']);
      }

      totalRupees = Math.round(employee) + Math.round(employers);

      rupeesINWord = converter.toWords(totalRupees).toUpperCase();

      const date = new Date();
      date.setMonth(month - 1);
      const monthName =
        date.toLocaleString('en-US', {
          month: 'short',
        }) +
        ' ' +
        year;

      const file = await readFile(filePath);

      const templateData = {
        companyaddress: branchData?.branchAddress || companyaddress,
        companyname,
        codeNo,
        NoEmployee,
        amount,
        employee,
        employers,
        rupeesINWord,
        totalRupees,
        monthName,

        // totalRupees: rupeesINWord
      };
      const template = Handlebars.compile(file);
      const htmlContent = template(templateData);
      const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox'],
        timeout: 120000,
      });

      const pdfPage = await browser.newPage();

      await pdfPage.setContent(htmlContent);

      const pdfBuffer = await pdfPage.pdf({
        format: 'A4',
        landscape: true,
        printBackground: true,
        timeout: 120000,
        margin: { top: '10px', bottom: '10px', left: '10px', right: '10px' },
      });

      await browser.close();
      const pdfBase64Path = Buffer.from(pdfBuffer).toString('base64');
      return res.status(200).json({
        status: 200,
        data: pdfBase64Path,
      });
    }

    return res.status(200).json({
      status: 200,
      message: 'ESIC Data got successfully',
      data: finaldata,
      companyregister: companyregister,
      companydata: companydata,
      totalcount: count,
    });
  } catch (err) {
    next(err);
  }
};

