exports.dailyInOutReport = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      Export,
      userMasterID,
      startDate,
      endDate,
      branchMasterID,
      departmentId,
    } = req.body;

    const condition = {};

    if (userMasterID && userMasterID.length > 0)
      condition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };

    if (startDate && endDate)
      condition.AttendanceDate = {
        [Sequelize.Op.between]: [startDate, endDate],
      };
    let branchName = '';

    if (branchMasterID) {
      const branch = await BranchMaster.findOne({
        raw: true,
        where: {
          branchMasterID: branchMasterID,
        },
      });
      branchName = branch.branchName;
    }
    let departName = '';
    if (departmentId) {
      const depart = await Department.findOne({
        raw: true,
        where: {
          departmentId: departmentId,
        },
      });
      departName = depart.departmentName;
    }

    const datesArray = await getDatesFromDateRange(
      new Date(startDate),
      new Date(endDate)
    );

    const [allUserData, allAttendanceData, allWeekoffHoliday, allLeaveData] =
      await Promise.all([
        UserMaster.findAll({
          raw: true,
          where: {
            userMasterID: userMasterID,
          },
          include: [
            { model: EmployeeJoiningDetails, attributes: ['employeeCode'] },
          ],
          order: [['displayName', 'ASC']],
        }),
        attendanceTransaction.findAll({
          raw: true,
          where: condition,
          include: [{ model: Shift, attributes: ['shiftName'] }],
        }),
        weekoffHolidayTran.findAll({
          raw: true,
          where: {
            userMasterID: userMasterID,
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
            [Sequelize.Op.or]: [
              { optionalHoliday: false },
              { optionalHoliday: null },
            ],
          },
        }),
        userLeaveTransaction.findAll({
          raw: true,
          where: {
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
            '$userLeave.userMasterID$': {
              [Sequelize.Op.in]: userMasterID,
            },
            status: 1,
          },
          include: [
            { model: UserLeave, attributes: [] },
            {
              model: hrLeaveTypes,
              attributes: [],
              include: [
                { model: HrLeaveMaster, as: 'LeaveMaster', attributes: [] },
              ],
            },
          ],
          attributes: [
            [sequelize.col('userLeave.userMasterID'), 'userMasterID'],
            'date',
            'days',
            [sequelize.col('hrLeaveType.LeaveMaster.LeaveName'), 'leaveName'],
          ],
        }),
      ]);

    const finalData = [];

    for (const userData of allUserData) {
      const user = userData.userMasterID;

      // const userData = allUserData.find(e => +e.userMasterID == +user);
      const attendanceData = allAttendanceData.filter(
        (e) => +e.userMasterID == +user
      );
      const weekoffHoliday = allWeekoffHoliday.filter(
        (e) => +e.userMasterID == +user
      );

      const attnTransIds = attendanceData.map((e) => e.AttendanceTransID);

      const allLogData = await AttendanceLogs.findAll({
        raw: true,
        where: {
          AttendanceTransID: attnTransIds,
        },
        order: [['logDateTime', 'ASC']],
      });

      const tempData = {
        EmployeeCode: userData['employeeJoiningDetails.employeeCode'],
        EmployeeName: userData.displayName,
        attendanceData: [],
      };
      let totalInhrs = 0,
        totalOshrs = 0;

      for (const date of datesArray) {
        const data = {};
        const currentdate = date.toISOString().slice(0, 10);
        data.AttendanceDate =
          currentdate.slice(8, 10) +
          '-' +
          norMonths[currentdate.slice(5, 7) - 1] +
          '-' +
          currentdate.slice(0, 4);
        const dateObj = new Date(currentdate);
        const days = [
          'Sunday',
          'Monday',
          'Tuesday',
          'Wednesday',
          'Thursday',
          'Friday',
          'Saturday',
        ];
        // Get the day name
        data.day = days[dateObj.getDay()];

        const attendance = attendanceData.find(
          (e) => e.AttendanceDate == currentdate
        );
        let inLog = [],
          outLog = [],
          totalHrs = 0,
          osHrs = 0,
          status = '',
          shift = '';

        const leave = allLeaveData.find(
          (e) => e.userMasterID == user && e.date == currentdate
        );

        if (leave) status = leave.leaveName;

        if (!leave && !attendance) status = 'A';

        if (attendance) {
          shift = attendance['shift.shiftName'];
          const logData = allLogData.filter(
            (e) => e.AttendanceTransID == attendance.AttendanceTransID
          );
          inLog = logData
            .filter((e) => e.direction == 'in')
            .map((t) => getTimeHHMMSSFormat(t.logDateTime));
          outLog = logData
            .filter((e) => e.direction == 'out')
            .map((t) => getTimeHHMMSSFormat(t.logDateTime));
          (totalHrs = +attendance.InHrs), (osHrs = +attendance.OutHrs);
          if (leave)
            status +=
              ' + ' +
              (inLog.length > outLog.length
                ? 'E'
                : attendance.fulldayhalfday == 1
                  ? 'P'
                  : attendance.fulldayhalfday == 0.5
                    ? 'HD'
                    : 'A');
          else
            status =
              inLog.length > outLog.length
                ? 'E'
                : attendance.fulldayhalfday == 1
                  ? 'P'
                  : attendance.fulldayhalfday == 0.5
                    ? 'HD'
                    : 'A';
        }

        if (!leave) {
          const findweekoffholiday = weekoffHoliday.find(
            (e) => e.date == currentdate
          );

          if (findweekoffholiday)
            status =
              status == 'A' && findweekoffholiday.tableName == 'weekoff'
                ? 'W'
                : status == 'A' && findweekoffholiday.tableName == 'holiday'
                  ? 'H'
                  : findweekoffholiday.tableName == 'weekoff'
                    ? status + 'W'
                    : findweekoffholiday.tableName == 'holiday'
                      ? status + 'H'
                      : status;
        }

        totalInhrs += +totalHrs;
        totalOshrs += +osHrs;

        data.shift = shift;
        data.inTime = inLog;
        data.outTime = outLog;
        data.totalHrs = minutesToHoursMinutes(totalHrs);
        data.OSHrs = minutesToHoursMinutes(osHrs);
        data.Status = status;
        tempData.attendanceData.push(data);
      }
      tempData.totalInHrs = minutesToHoursMinutes(totalInhrs);
      tempData.totalOsHrs = minutesToHoursMinutes(totalOshrs);

      finalData.push(tempData);
    }

    const companyData = await companyMaster.findOne({
      raw: true,
      where: {
        companyMasterID: companyMasterID,
      },
    });

    const startdate =
      startDate.slice(8, 10) +
      '-' +
      norMonths[startDate.slice(5, 7) - 1] +
      '-' +
      startDate.slice(0, 4);

    const enddate =
      endDate.slice(8, 10) +
      '-' +
      norMonths[endDate.slice(5, 7) - 1] +
      '-' +
      endDate.slice(0, 4);

    if (Export == 'pdf') {
      const pdfData = {
        startdate: startdate,
        enddate: enddate,
        companyName: companyData.companyName,
        companyAddress: companyData.companyAddress,
        branch: branchName,
        department: departName,
        data: finalData,
      };

      const getTemplate1 = (type) => {
        const file = path.join(__dirname, `../html/${type}.html`);
        return file;
      };

      const filePath = await getTemplate1('dailyinoutreport');

      const file = await readFile(filePath);
      const template = Handlebars.compile(file);
      const html = template(pdfData);

      const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox'],
      });
      const page = await browser.newPage();

      // Set the HTML content of the page
      await page.setContent(html);

      // Generate PDF
      const pdfBuffer = await page.pdf({
        format: 'A4', // Page format (A4 in this case)
        printBackground: true, // print background
        margin: { top: '10px', bottom: '10px' },
        // landscape: true, // Set PDF to landscape mode
      });
      await browser.close();

      let base64path = Buffer.from(pdfBuffer).toString('base64');

      return res.status(200).json({
        status: 200,
        data: base64path,
      });
    }

    return res.status(200).json({
      status: 200,
      companyName: companyData.companyName,
      compnayAdderess: companyData.companyAddress,
      data: finalData,
    });
  } catch (error) {
    next(error);
  }
};

exports.addGratuity = async (req, res, next) => {
  try {
    const companyData = await companyMasters.findAll({
      raw: true,
      where: {
        status: [0, 1],
      },
    });

    const finalData = [];

    for (const company of companyData) {
      const findGratuity = await HRSalaryFields.findOne({
        where: {
          payheadMasterId: 83,
          status: 1,
        },
      });

      if (!findGratuity) {
        finalData.push({
          salaryFieldActive: 'Y',
          payheadMasterId: 83,
          salaryFieldSide: 'E',
          salaryFieldAttanChk: 1,
          salaryFieldRound: 'Y',
          salaryFieldSrNo: 'A',
          salaryFieldShow: 'Y',
          salaryFieldWhenMonth: [0],
          companyMasterID: company.companyMasterID,
          createBy: 4,
        });
      }
    }

    await sequelize.transaction(async (t) => {
      await HRSalaryFields.bulkCreate(finalData, { transaction: t });
    });

    return res.status(200).json({
      status: 200,
      message: 'Gratuity added successfully.',
    });
  } catch (error) {
    next(error);
  }
};

exports.monthlyAttendanceReport = async (req, res, next) => {
  try {
    const { companyMasterID, userMasterID, month } = req.body;

    if (
      !companyMasterID ||
      !month ||
      !(userMasterID && userMasterID.length > 0)
    )
      return res.status(200).json({
        status: 401,
        message: 'companyMasterID, month and userMasterID are required fields!',
      });

    const currentmonth =
      new Date().toISOString().slice(0, 4) +
      new Date().toISOString().slice(5, 7);

    if (currentmonth < month)
      return res.status(200).json({
        status: 401,
        message: 'you can not select future month!',
      });

    const days = [
      'Sunday',
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
    ];

    const startDate =
      month.toString().slice(0, 4) +
      '-' +
      month.toString().slice(4, 6) +
      '-' +
      '01';

    const endDate =
      month.toString().slice(0, 4) +
      '-' +
      month.toString().slice(4, 6) +
      '-' +
      daysInMonth(month.slice(4, 6), month.slice(0, 4));

    // let userdata = [];
    const finalData = [];

    // if (companyMasterID && !branchMasterID) {
    let startdate = startDate,
      enddate = endDate;

    const userdata = await EmployeeJoiningDetails.findAll({
      raw: true,
      where: {
        joiningDate: {
          [Sequelize.Op.lte]: new Date(enddate),
        },
        userMasterID: {
          [Sequelize.Op.in]: userMasterID,
        },
        [Sequelize.Op.or]: [
          {
            leavingDate: { [Sequelize.Op.gte]: new Date(startdate) },
          },
          {
            leavingDate: { [Sequelize.Op.eq]: null },
            [Sequelize.Op.or]: [
              {
                '$userMaster.deactiveDate$': {
                  [Sequelize.Op.gte]: new Date(startdate),
                },
              },
              {
                '$userMaster.deactiveDate$': { [Sequelize.Op.eq]: null },
              },
            ],
          },
        ],
        '$userMaster.companyMasterId$': companyMasterID,
        '$userMaster.status$': [0, 1],
      },

      include: [
        {
          model: UserMaster,
          required: true,
          ...accessibleUsers(req.userDetails),
        },
      ],
      order: [[{ model: UserMaster }, 'displayName', 'ASC']],
    });

    // userdata = userdata1.rows;
    // }

    // if (branchMasterID) {
    //   let startdate = startDate,
    //     enddate = endDate;
    //   const get_branch_users = await EmployeeBranch.findAndCountAll({
    //     raw: true,
    //     where: {
    //       branchID: branchMasterID,
    //       applicableDate: {
    //         [Sequelize.Op.lte]: new Date(enddate),
    //       },
    //       [Sequelize.Op.or]: [
    //         {
    //           endDate: {
    //             [Sequelize.Op.gte]: new Date(startdate),
    //           },
    //         },
    //         {
    //           endDate: null,
    //         },
    //       ],
    //       status: 1,
    //     },
    //   });
    //   let allActiveUsersID = [];
    //   for (let userID of get_branch_users.rows) {
    //     allActiveUsersID.push(userID.userMasterID);
    //   }

    //   const userdata1 = await EmployeeJoiningDetails.findAndCountAll({
    //     raw: true,
    //     where: {
    //       joiningDate: {
    //         [Sequelize.Op.lte]: new Date(enddate),
    //       },
    //       [Sequelize.Op.or]: [
    //         {
    //           leavingDate: { [Sequelize.Op.gte]: new Date(startdate) },
    //         },
    //         {
    //           leavingDate: { [Sequelize.Op.eq]: null },
    //           [Sequelize.Op.or]: [
    //             {
    //               '$userMaster.deactiveDate$': {
    //                 [Sequelize.Op.gte]: new Date(startdate),
    //               },
    //             },
    //             {
    //               '$userMaster.deactiveDate$': { [Sequelize.Op.eq]: null },
    //             },
    //           ],
    //         },
    //       ],
    //       userMasterID: allActiveUsersID,
    //       '$userMaster.status$': [0, 1],
    //     },

    //     include: [
    //       {
    //         model: UserMaster,
    //         required: true,
    //         ...accessibleUsers(req.userDetails),
    //       },
    //     ],
    //     order: [[{ model: UserMaster }, 'displayName', 'ASC']],
    //   });

    //   userdata1.rows.forEach((row) => {
    //     const branchData = get_branch_users.rows.find(
    //       (user) => user.userMasterID === row.userMasterID
    //     );
    //     if (branchData) {
    //       row.branchStartDate = branchData.applicableDate;
    //       row.branchEndDate = branchData.endDate;
    //     }
    //   });

    //   userdata = userdata1.rows;
    // }

    // let userIds = userdata.map((e) => e.userMasterID);

    let userIds = [];

    if (userMasterID && userMasterID.length > 0) userIds = userMasterID;

    const currentMonth =
      month_dict[month.toString().slice(4, 6)] +
      ' - ' +
      month.toString().slice(0, 4);

    const [allAttendanceData, allWeekoffHoliday, allLeaveData] =
      await Promise.all([
        attendanceTransaction.findAll({
          raw: true,
          where: {
            userMasterID: {
              [Sequelize.Op.in]: userIds,
            },
            AttendanceDate: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
          },
          include: [{ model: Shift, attributes: ['shiftName'] }],
        }),
        weekoffHolidayTran.findAll({
          raw: true,
          where: {
            userMasterID: {
              [Sequelize.Op.in]: userIds,
            },
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
            [Sequelize.Op.or]: [
              { optionalHoliday: false },
              { optionalHoliday: null },
            ],
          },
        }),
        userLeaveTransaction.findAll({
          raw: true,
          where: {
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
            '$userLeave.userMasterID$': {
              [Sequelize.Op.in]: userIds,
            },
            status: 1,
          },
          include: [
            { model: UserLeave, attributes: [] },
            {
              model: hrLeaveTypes,
              attributes: [],
              include: [
                { model: HrLeaveMaster, as: 'LeaveMaster', attributes: [] },
              ],
            },
          ],
          attributes: [
            [sequelize.col('userLeave.userMasterID'), 'userMasterID'],
            'date',
            'days',
            [sequelize.col('hrLeaveType.LeaveMaster.LeaveName'), 'leaveName'],
          ],
        }),
      ]);

    const shiftIds = allAttendanceData.map((e) => e.Shift);

    const allShiftTimes = await ShiftTIme.findAll({
      raw: true,
      where: {
        shiftID: {
          [Sequelize.Op.in]: shiftIds,
        },
      },
    });

    const datesArray = await getDatesFromDateRange(
      new Date(startDate),
      new Date(endDate)
    );

    for (const user of userIds) {
      const userDetails = userdata.find((e) => +e.userMasterID == +user);

      if (!userDetails) continue;

      const designation = await employeeDesignation(user, endDate);

      const tempData = {
        EmployeeCode:
          userDetails && userDetails['employeeCode']
            ? userDetails['employeeCode']
            : '',

        EmployeeName: userDetails['userMaster.displayName'],
        Designation: designation
          ? designation['designation.designationName']
          : '',
        month: currentMonth,
        attendanceData: [],
      };
      let present = 0,
        totalleave = 0,
        weekoff = 0;

      for (const date of datesArray) {
        const data = {};
        const currentdate = date.toISOString().slice(0, 10);
        data.AttendanceDate =
          currentdate.slice(8, 10) +
          '-' +
          currentdate.slice(5, 7) +
          '-' +
          currentdate.slice(0, 4);

        const attendance = allAttendanceData.find(
          (e) => e.AttendanceDate == currentdate && +e.userMasterID == +user
        );

        const weekoffholiday = allWeekoffHoliday.find(
          (e) => e.date == currentdate && +e.userMasterID == +user
        );

        const leave = allLeaveData.find(
          (e) => +e.userMasterID == +user && e.date == currentdate
        );

        let shift = '',
          inTime = '',
          outTime = '',
          status = '';

        if (attendance) {
          // find day of date
          const dayOfWeek = date.getDay();
          const dayName = days[dayOfWeek];

          const shiftTimes = allShiftTimes.find(
            (e) => e.shiftID == attendance.Shift && e.day == dayName
          );
          shift =
            attendance['shift.shiftName'] +
            ' - ' +
            `(${
              shiftTimes ? shiftTimes.statTime + ' - ' + shiftTimes.endtime : ''
            })`;
          inTime = asiaKolkataDateTime(attendance.InDatetime);
          outTime = asiaKolkataDateTime(attendance.OutDateTime);
          status =
            attendance.fulldayhalfday == 1
              ? 'P'
              : attendance.fulldayhalfday == 0.5
                ? 'HD'
                : 'A';
          if (!weekoffholiday) present += +attendance.fulldayhalfday;

          if (attendance.fulldayhalfday != 1 && leave) {
            status += `+${leave.leaveName}`;
            totalleave += attendance.fulldayhalfday == 0.5 ? 0.5 : +leave.days;
          }
        }

        if (!leave && weekoffholiday) {
          status +=
            weekoffholiday.tableName == 'weekoff'
              ? attendance
                ? '+WH'
                : 'WH'
              : attendance
                ? '+PH'
                : 'PH';
          weekoff += +weekoffholiday.value;
        }

        if (!attendance && leave) {
          status += `${leave.leaveName}`;
          totalleave += +leave.days;
        }

        data.Shift = shift || '';
        data.InTime = inTime || '';
        data.OutTime = outTime || '';
        data.Status = status || 'A';

        tempData.attendanceData.push(data);
      }

      tempData.monthDays = datesArray.length;
      tempData.present = present;
      tempData.absent =
        datesArray.length - (+present + +totalleave + +weekoff) < 0
          ? 0
          : datesArray.length - (+present + +totalleave + +weekoff);
      tempData.totalleave = +totalleave;
      tempData.weekoffHoliday = +weekoff;

      finalData.push(tempData);
    }

    if (finalData.length === 0)
      return res.status(200).json({
        status: 401,
        message: 'No data found to export!',
      });

    const company = await companyMaster.findOne({
      raw: true,
      where: {
        companyMasterID: companyMasterID,
      },
    });

    return await generateExcelForMonthlyAttendanceReport(
      finalData,
      company ? company.companyName : '',
      'Monthly Attendance Report',
      'xlsx',
      res
    );
  } catch (error) {
    next(error);
  }
};

