exports.employeeWiseSalaryReport = async (req, res, next) => {
  try {
    const {
      userMasterID,
      startMonth,
      endMonth,
      dayType,
      exportData,
      page,
      limit,
    } = req.body;

    if (!userMasterID || !startMonth || !endMonth || !dayType)
      return res.status(400).json({
        status: 401,
        message:
          'userMasterID,startMonth,endMonth,dayType are required fields!',
      });

    const paginationQuery = {};

    const currentdate = asiaKolkataDateTime(new Date()).slice(0, 10);

    if (page && limit && !exportData) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = limit;
    }

    const includeArray = [
      {
        required: false,
        model: HrSalaryTransaction,
        where: {
          salaryYYYYMM: {
            [Sequelize.Op.between]: [startMonth, endMonth],
          },
        },
        include: [
          {
            model: HrSalaryMaster,
            as: 'HSM',
            attributes: ['gradeSalaryStructureID', 'EmployeeSalaryAmount'],
            include: [
              {
                model: GradeSalaryStructure,
                as: 'GSS',
                attributes: ['salaryFieldID', 'salaryfieldindex'],
                include: [
                  {
                    model: HRSalaryFields,
                    as: 'HSF',
                    where: {
                      salaryFieldSrNo: {
                        [Sequelize.Op.ne]: 'C',
                      },
                    },
                    attributes: [
                      'salaryFieldSrNo',
                      'salaryFieldSide',
                      'considerIn',
                      'payheadDisplayName',
                      'payheadMasterId',
                    ],
                    include: [
                      {
                        model: Payheadmaster,
                        as: 'PHM',
                        attributes: ['payheadName'],
                      },
                    ],
                  },
                ],
              },
            ],
          },
          {
            required: false,
            model: EmployeePenalty,
            include: [
              { model: Penalty, as: 'penalty', attributes: ['penaltyName'] },
            ],
          },
          {
            required: false,
            model: EmployeeIncentive,
            include: [
              {
                model: Incentivetype,
                as: 'IncType',
                attributes: [
                  ['incentivetypename', 'name'],
                  ['inc_type_displayName', 'displayName'],
                  ['IncentivetypeID', 'id'],
                ],
              },
            ],
          },
        ],
      },
      {
        model: EmployeeBranch,
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: new Date(currentdate),
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: new Date(currentdate),
              },
            },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['branchID'],
        include: [
          {
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDesignation,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(currentdate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(currentdate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      {
        required: false,
        model: EmployeeDepartment,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(currentdate) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(currentdate) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['departmentID'],
        include: [
          {
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      {
        model: companyMaster,
        required: true,
        attributes: ['companyMasterID', 'companyName', 'fileUploadType'],
      },
      {
        model: EmployeeJoiningDetails,
        attributes: ['employeeCode', 'joiningDate'],
        required: true,
      },
    ];

    if (dayType == 'present') {
      includeArray.push({
        required: false,
        model: HrLeaveMonthlyTrans,
        where: {
          AttnYearMon: {
            [Sequelize.Op.between]: [startMonth, endMonth],
          },
        },
        attributes: [
          'userMasterID',
          'AttnYearMon',
          'AttnVal',
          'monthstartdate',
          'monthenddate',
        ],
        include: [{ model: hrLeaveTypes, attributes: ['LeaveID'] }],
      });
    }

    const { rows, count } = await UserMaster.findAndCountAll({
      distinct: true,
      where: {
        userMasterID: {
          [Sequelize.Op.in]: userMasterID,
        },
      },
      include: includeArray,
      ...paginationQuery,
      order: [['displayName', 'ASC']],
    });

    const salaryData = [];
    rows.map((row) => {
      const data = {};

      data.userMasterID = row.userMasterID;
      data.companyMasterID = row.companyMasterId;
      data.displayName = row.displayName;
      data.email = row.email;
      data.photo = row.photo;
      data.userNumber = row.userNumber;
      data.branch = row?.employeeBranches[0].branchMaster.branchName || '';
      data.designation =
        row?.employeeDesignations[0]?.designation.designationName || '';
      data.department =
        row?.employeeDepartments[0]?.department.departmentName || '';
      data.employeeCode = row?.employeeJoiningDetails[0]?.employeeCode || '';
      data.joiningDate = row?.employeeJoiningDetails[0]?.joiningDate || '';
      data.salaryData = [];

      data.total = {};
      const achildSum = [];
      const bchildSum = [];
      const extraChildSum = [];
      const grossSum = [];
      const netPaySum = [];

      const salary = row.hrSalaryTrasactions || [];

      const groupedData = row.hrSalaryTrasactions
        ?.sort((a, b) => {
          // First, sort by salaryfieldindex
          const indexA = a.HSM?.GSS?.salaryfieldindex ?? Infinity;
          const indexB = b.HSM?.GSS?.salaryfieldindex ?? Infinity;

          if (indexA !== indexB) {
            return indexA - indexB;
          }

          // If salaryfieldindex is the same, sort by payheadDisplayName
          const nameA =
            a.HSM?.GSS?.HSF?.PHM.payheadDisplayName?.toLowerCase() || '';
          const nameB =
            b.HSM?.GSS?.HSF?.PHM.payheadDisplayName?.toLowerCase() || '';

          if (nameA !== nameB) {
            return nameA.localeCompare(nameB);
          }

          // If payheadDisplayName is also the same, sort by payheadName
          const payheadNameA =
            a.HSM?.GSS?.HSF?.PHM?.payheadName?.toLowerCase() || '';
          const payheadNameB =
            b.HSM?.GSS?.HSF?.PHM?.payheadName?.toLowerCase() || '';

          return payheadNameA.localeCompare(payheadNameB);
        })
        .reduce((acc, obj) => {
          const days = row.hrLeaveMonthlyTrans?.find(
            (a) =>
              a.AttnYearMon == obj.salaryYYYYMM && a.hrLeaveType.LeaveID == 1
          );

          const salaryFromYYYYMM = obj.salaryYYYYMM;

          if (!acc[salaryFromYYYYMM]) {
            acc[salaryFromYYYYMM] = {
              salaryFromYYYYMM:
                month_dict[String(salaryFromYYYYMM).slice(4, 6)] +
                ' ' +
                String(salaryFromYYYYMM).slice(0, 4),
              achildData: [],
              bchildData: [],
              extra_achild: [],
              grossData: null,
              netPayData: null,
              salary_Cal: false,
              salaryMasterID: obj.salaryMasterID,
              salaryScale: null,
              days: dayType == 'present' ? days.AttnVal : obj.SalaryCalcOnDays,
            };
          }

          if (!acc[salaryFromYYYYMM].salary_Cal) {
            if (salary?.find((e) => e.salaryMasterID == obj.salaryMasterID))
              acc[salaryFromYYYYMM].salary_Cal = true;
          }

          const avoidIds = [24, 34, 1, 50, 92];

          if (!avoidIds.includes(obj.HSM?.GSS?.HSF.payheadMasterId)) {
            if (
              obj.HSM?.GSS?.HSF.salaryFieldSrNo == 'A' &&
              obj.HSM?.GSS?.HSF.considerIn != 'net' &&
              obj.EmployeeSalaryAmount > 0
            ) {
              acc[salaryFromYYYYMM].achildData.push({
                salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
                salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
                EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
                considerIn: obj.HSM?.GSS?.HSF.considerIn,
                payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
                payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
              achildSum.push({
                salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
                salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
                EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
                considerIn: obj.HSM?.GSS?.HSF.considerIn,
                payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
                payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
            }

            if (
              obj.HSM?.GSS?.HSF.salaryFieldSrNo == 'A' &&
              obj.HSM?.GSS?.HSF.considerIn == 'net' &&
              obj.EmployeeSalaryAmount > 0
            ) {
              acc[salaryFromYYYYMM].extra_achild.push({
                salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
                salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
                EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
                considerIn: obj.HSM?.GSS?.HSF.considerIn,
                payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
                payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
              extraChildSum.push({
                salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
                salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
                EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
                considerIn: obj.HSM?.GSS?.HSF.considerIn,
                payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
                payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
            }
            if (
              obj.HSM?.GSS?.HSF.salaryFieldSrNo == 'B' &&
              obj.EmployeeSalaryAmount > 0
            ) {
              acc[salaryFromYYYYMM].bchildData.push({
                salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
                salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
                EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
                considerIn: obj.HSM?.GSS?.HSF.considerIn,
                payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
                payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
              bchildSum.push({
                salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
                salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
                EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
                considerIn: obj.HSM?.GSS?.HSF.considerIn,
                payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
                payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
            }
          }

          if (obj.employeeincentives && Array.isArray(obj.employeeincentives)) {
            obj.employeeincentives.forEach((incentive) => {
              const incentiveType = incentive.IncType.dataValues.displayName
                ? incentive.IncType.dataValues.displayName
                : incentive.IncType.dataValues.name;

              const existingIncentive = acc[salaryFromYYYYMM].achildData.find(
                (incentiveItem) =>
                  incentiveItem.IncentivetypeID == incentive.IncentivetypeID
              );

              if (existingIncentive) {
                existingIncentive.EmployeeSalaryAmount += +incentive.amount;
              } else {
                acc[salaryFromYYYYMM].achildData.push({
                  payheadDisplayName: incentiveType,
                  EmployeeSalaryAmount: incentive.amount,
                  incentiveDate: incentive.incentiveDate,
                  payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
                  IncentivetypeID: incentive.IncentivetypeID,
                });
              }
              achildSum.push({
                payheadDisplayName: incentiveType,
                EmployeeSalaryAmount: incentive.amount,
                incentiveDate: incentive.incentiveDate,
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
                IncentivetypeID: incentive.IncentivetypeID,
              });
            });
          }

          if (obj.employeePenalties && Array.isArray(obj.employeePenalties)) {
            obj.employeePenalties.forEach((penalty) => {
              // Find if this penalty already exists in the array
              const existingPenalty = acc[salaryFromYYYYMM].bchildData.find(
                (penaltyItem) => penaltyItem.penaltyID === penalty.penaltyID
              );

              if (existingPenalty) {
                existingPenalty.penaltyAmount += parseFloat(
                  penalty.penaltyAmount
                );
              } else {
                acc[salaryFromYYYYMM].bchildData.push({
                  payheadName: penalty.penalty?.penaltyName,
                  penaltyID: penalty?.penaltyID,
                  EmployeeSalaryAmount: parseFloat(penalty.penaltyAmount),
                  payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
                });
              }
              bchildSum.push({
                payheadName: penalty.penalty?.penaltyName,
                penaltyID: penalty?.penaltyID,
                EmployeeSalaryAmount: parseFloat(penalty.penaltyAmount),
                payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
              });
            });
          }

          if (obj.HSM?.GSS?.HSF.payheadMasterId == 50) {
            acc[salaryFromYYYYMM].grossData = {
              salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
              salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
              EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
              considerIn: obj.HSM?.GSS?.HSF.considerIn,
              payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
              payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
              payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
            };

            acc[salaryFromYYYYMM].salaryScale = {
              salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
              salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
              EmployeeSalaryAmount: obj.HSM.EmployeeSalaryAmount,
              considerIn: obj.HSM?.GSS?.HSF.considerIn,
              payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
              payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
              payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
            };

            grossSum.push({
              salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
              salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
              EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
              considerIn: obj.HSM?.GSS?.HSF.considerIn,
              payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
              payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
              payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
            });
          }
          if (obj.HSM?.GSS?.HSF.payheadMasterId == 92) {
            acc[salaryFromYYYYMM].netPayData = {
              salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
              salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
              EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
              considerIn: obj.HSM?.GSS?.HSF.considerIn,
              payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
              payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
              payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
            };
            netPaySum.push({
              salaryFieldSrNo: obj.HSM?.GSS?.HSF.salaryFieldSrNo,
              salaryFieldSide: obj.HSM?.GSS?.HSF.salaryFieldSide,
              EmployeeSalaryAmount: obj.EmployeeSalaryAmount,
              considerIn: obj.HSM?.GSS?.HSF.considerIn,
              payheadDisplayName: obj.HSM?.GSS?.HSF.payheadDisplayName,
              payheadName: obj.HSM?.GSS?.HSF.PHM.payheadName,
              payheadMasterId: obj.HSM?.GSS?.HSF.payheadMasterId,
            });
          }
          return acc;
        }, {});

      data.salaryData = Object.values(groupedData);

      function calAchildSum(data) {
        const groupedData = {};

        data.forEach((item) => {
          // Determine the key based on the presence of IncentivetypeID
          const key = item.IncentivetypeID || item.payheadMasterId;

          if (!groupedData[key]) {
            groupedData[key] = { ...item }; // Clone the first occurrence
          } else {
            groupedData[key].EmployeeSalaryAmount += item.EmployeeSalaryAmount; // Sum salary
          }
        });

        return Object.values(groupedData);
      }

      function calBchildSum(data) {
        const groupedData = {};

        data.forEach((item) => {
          // Determine the key based on the presence of IncentivetypeID
          const key = item.penaltyID || item.payheadMasterId;

          if (!groupedData[key]) {
            groupedData[key] = { ...item }; // Clone the first occurrence
          } else {
            groupedData[key].EmployeeSalaryAmount += item.EmployeeSalaryAmount; // Sum salary
          }
        });

        return Object.values(groupedData);
      }

      data.total.achildSum = calAchildSum(achildSum);
      data.total.bchildSum = calBchildSum(bchildSum);

      data.total.extraAChildSum = Object.values(
        extraChildSum.reduce((acc, item) => {
          const id = item.payheadMasterId;
          const amount = item.EmployeeSalaryAmount;

          // If this payheadMasterId already exists in the accumulator, add the amount to it
          if (acc[id]) {
            acc[id].EmployeeSalaryAmount += amount; // Sum the amounts
          } else {
            // If it doesn't exist, initialize it with the current item
            acc[id] = { ...item };
          }

          return acc;
        }, {})
      );

      data.total.grossSum = Object.values(
        grossSum.reduce((acc, item) => {
          const id = item.payheadMasterId;
          const amount = item.EmployeeSalaryAmount;

          // If this payheadMasterId already exists in the accumulator, add the amount to it
          if (acc[id]) {
            acc[id].EmployeeSalaryAmount += amount; // Sum the amounts
          } else {
            // If it doesn't exist, initialize it with the current item
            acc[id] = { ...item, EmployeeSalaryAmount: amount };
          }

          return acc;
        }, {})
      )[0];

      data.total.netPaySum = Object.values(
        netPaySum.reduce((acc, item) => {
          const id = item.payheadMasterId;
          const amount = item.EmployeeSalaryAmount;

          // If this payheadMasterId already exists in the accumulator, add the amount to it
          if (acc[id]) {
            acc[id].EmployeeSalaryAmount += amount; // Sum the amounts
          } else {
            // If it doesn't exist, initialize it with the current item
            acc[id] = { ...item, EmployeeSalaryAmount: amount };
          }

          return acc;
        }, {})
      )[0];

      salaryData.push(data);
    });

    if (!exportData) {
      return res.status(200).json({
        status: 200,
        data: salaryData,
        totalCount: count,
      });
    } else if (exportData == 'excel') {
      generateExcelForEmploeeMonthWiseSalary(
        salaryData,
        'Employee Month Wise Salary Report',
        'xlsx',
        res
      );
    } else if (exportData == 'pdf') {
      generatePdfForEmploeeMonthWiseSalary(
        salaryData,
        'Employee Month Wise Salary Report',
        'pdf',
        res
      );
    }
  } catch (error) {
    next(error);
  }
};

exports.employeeWiseSalaryReport_new = async (req, res, next) => {
  try {
    const { userMasterID, startMonth, endMonth, dayType, Export } = req.body;

    if (!isArray(userMasterID) || !startMonth || !endMonth || !dayType)
      return res.status(200).json({
        status: 401,
        message:
          'userMasterID,startMonth,endMonth,dayType are required fields!',
      });

    const date =
      String(endMonth).slice(0, 4) +
      '-' +
      String(endMonth).slice(4, 6) +
      '-' +
      daysInMonth(String(endMonth).slice(4, 6), String(endMonth).slice(0, 4));

    const includeArray = [
      // salary data
      {
        separate: true,
        required: false,
        model: HrSalaryTransaction,
        where: {
          '$hrSalaryMaster.gradeSalaryStructure.hrSalaryField.salaryFieldSrNo$':
            {
              [Sequelize.Op.ne]: 'C',
            },
          salaryYYYYMM: {
            [Sequelize.Op.between]: [startMonth, endMonth],
          },
          [Sequelize.Op.or]: [
            {
              '$hrSalaryMaster.gradeSalaryStructure.hrSalaryField.payheadMasterId$':
                {
                  [Sequelize.Op.notIn]: [
                    16, 17, 9, 24, 34, 43, 78, 83, 96, 97, 99,
                  ],
                },
            },
            { EmployeeSalaryAmount: { [Sequelize.Op.ne]: 0 } },
          ],
        },

        include: [
          {
            model: HrSalaryMaster,
            include: [
              {
                model: GradeSalaryStructure,
                include: [
                  {
                    model: HRSalaryFields,
                    attributes: [],
                    include: [
                      {
                        model: Payheadmaster,
                        attributes: [],
                      },
                    ],
                  },
                ],
                attributes: [],
              },
            ],
            attributes: [],
          },
        ],
        attributes: [
          'EmployeeSalaryAmount',
          'salaryYYYYMM',
          [
            Sequelize.col(
              'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.payheadMasterId'
            ),
            'payheadMasterId',
          ],
          [
            Sequelize.col(
              'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.Payheadmaster.payheadName'
            ),
            'payheadName',
          ],
          [
            Sequelize.col(
              'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.salaryFieldSrNo'
            ),
            'salaryFieldSrNo',
          ],
        ],
        order: [
          // Order by salaryfieldindex in GradeSalaryStructure
          [
            { model: HrSalaryMaster, as: 'hrSalaryMaster' },
            { model: GradeSalaryStructure, as: 'gradeSalaryStructure' },
            'salaryfieldindex',
            'ASC',
          ],

          // Order by payheadName in Payheadmaster
          [
            { model: HrSalaryMaster, as: 'hrSalaryMaster' },
            { model: GradeSalaryStructure, as: 'gradeSalaryStructure' },
            { model: HRSalaryFields, as: 'hrSalaryField' },
            { model: Payheadmaster, as: 'Payheadmaster' },
            'payheadName',
            'ASC',
          ],
        ],
      },
      //  branch
      {
        model: EmployeeBranch,
        where: {
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: new Date(date),
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: new Date(date),
              },
            },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },
        required: false,
        attributes: ['branchID'],
        include: [
          {
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      },
      //designation
      {
        required: false,
        model: EmployeeDesignation,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(date) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(date) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      },
      // department
      {
        required: false,
        model: EmployeeDepartment,
        where: {
          status: 1,
          applicableDate: { [Sequelize.Op.lte]: new Date(date) },
          [Sequelize.Op.or]: [
            { endDate: { [Sequelize.Op.gte]: new Date(date) } },
            { endDate: { [Sequelize.Op.eq]: null } },
          ],
        },

        attributes: ['departmentID'],
        include: [
          {
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      },
      // attendancepolicy
      {
        model: EmployeeAttendancePolicy,
        where: {
          status: 1,
          // startDate: {
          //   [Sequelize.Op.lte]: new Date(date),
          // },
          // [Sequelize.Op.or]: [
          //   {
          //     endDate: {
          //       [Sequelize.Op.gte]: new Date(date),
          //     },
          //   },
          //   { endDate: { [Sequelize.Op.eq]: null } },
          // ],
        },
        required: false,
        attributes: ['attendancePolicyID'],
        include: [
          {
            model: AttendancePolicy,
            as: 'attendancePolicy',
            attributes: ['showinsalaryslip', 'consider'],
          },
        ],
      },
      //

      // {
      //   model: companyMaster,
      //   required: true,
      //   attributes: ['companyMasterID', 'companyName', 'fileUploadType'],
      // },
      {
        model: EmployeeJoiningDetails,
        attributes: ['employeeCode', 'joiningDate'],
        required: true,
      },
    ];

    const userData = await UserMaster.findAll({
      where: { userMasterID: { [Sequelize.Op.in]: userMasterID } },
      include: includeArray,
      attributes: ['userMasterID', 'displayName'],
      order: [['displayName', 'ASC']],
    });

    return res.status(200).json({
      status: 200,
      data: userData,
    });

    const allsalary = await getAllSalaryDataByRange(
      userMasterID,
      startMonth,
      endMonth
    );

    const range = await getYearMonthByRange(startMonth, endMonth);
    let attnData = [];

    if (dayType == 'present') {
      attnData = await hrLeaveMonthlyTrans.findAll({
        raw: true,
        where: {
          userMasterID: userMasterID,
          AttnYearMon: {
            [Sequelize.Op.in]: range,
          },
          verified: 1,
        },
        include: [
          {
            model: hrLeaveTypes,
            where: { LeaveID: 1 },
            attributes: ['LeaveID'],
          },
        ],
      });
    }

    // const filteredSalary = allsalary.filter(e => e.salaryFieldSrNo != 'C' || ((e.salaryFieldSrNo == 'B' && +e.EmployeeSalaryAmount > 0) || (e.salaryFieldSrNo == 'D' && +e.EmployeeSalaryAmount > 0)));

    const data1 = allsalary.map((monthData) => {
      if (monthData.salaryData.length > 0) {
        // Filter salaryData array based on the condition salaryFieldSrNo !== 'C'
        const filteredSalaryData = monthData.salaryData.filter(
          (salary) =>
            salary.salaryFieldSrNo !== 'C' &&
            ((salary.salaryFieldSrNo == 'B' &&
              +salary.EmployeeSalaryAmount > 0) ||
              (salary.salaryFieldSrNo == 'D' &&
                +salary.EmployeeSalaryAmount > 0) ||
              salary.salaryFieldSrNo == 'A')
        );
        // calculate salary
        const result = filteredSalaryData.reduce(
          (acc, e) => {
            if (e.salaryFieldSrNo === 'A' && e.considerIn != 'net') {
              if (e.payheadMasterId !== 24 && e.payheadMasterId !== 43) {
                acc.gross += +e.EmployeeSalaryAmount;
              } else if (e.consider === 'gross') {
                acc.otherData += +e.EmployeeSalaryAmount;
              }
            } else if (e.salaryFieldSrNo === 'B') {
              acc.deduction += +e.EmployeeSalaryAmount;
            }

            // for loan and advance and penalty
            if (
              e.salaryFieldSrNo === 'D' &&
              (e.payheadMasterId === 16 ||
                e.payheadMasterId === 17 ||
                e.payheadMasterId === 34)
            ) {
              acc.deduction += +e.EmployeeSalaryAmount;
            }

            if (
              ((e.payheadMasterId === 24 || e.payheadMasterId === 43) &&
                e.consider === 'net') ||
              (e.salaryFieldSrNo === 'A' && e.considerIn == 'net')
            ) {
              acc.toAddNetAmount += +e.EmployeeSalaryAmount;
            }

            return acc;
          },
          { gross: 0, otherData: 0, deduction: 0, toAddNetAmount: 0 }
        );

        const grossAmount = result.gross + result.otherData;
        const netpay = grossAmount - result.deduction;
        const deductionAmount = result.deduction;
        const netPayAmount = netpay + result.toAddNetAmount;

        const actualGross = monthData.salaryData
          .filter((e) => e.salaryFieldSrNo == 'A' && e.considerIn != 'net')
          .reduce((acc, obj) => acc + +obj.actualAmount, 0);
        let totalDays = 0;

        //totalDays calculation
        if (monthData.salaryData[0].baseOnCalculation == 'H') {
          totalDays = minutesToHoursMinutes(
            +monthData.salaryData[0].SalaryCalcOnDays
          );
        } else {
          if (dayType == 'present') {
            const presentDay = attnData.find(
              (e) =>
                e.AttnYearMon == +monthData.month &&
                e['hrLeaveType.LeaveID'] == 1
            );

            totalDays = +presentDay.AttnVal;
          } else {
            totalDays = +monthData.salaryData[0].SalaryCalcOnDays;
          }
        }

        const earningPayHead = filteredSalaryData
          .filter((e) => e.salaryFieldSrNo == 'A' && e.considerIn != 'net')
          .map((e) => ({
            ...e,
            payheadName:
              e.payheadDisplayName && e.payheadDisplayName.trim()
                ? e.payheadDisplayName
                : e.payheadName,
          }));
        // Extra earninh payhead
        const extra_earningPayHead = filteredSalaryData
          .filter((e) => e.salaryFieldSrNo == 'A' && e.considerIn == 'net')
          .map((e) => ({
            ...e,
            payheadName:
              e.payheadDisplayName && e.payheadDisplayName.trim()
                ? e.payheadDisplayName
                : e.payheadName,
          }));

        const deductionPayHead = filteredSalaryData
          .filter((e) => e.salaryFieldSrNo != 'A')
          .map((e) => ({
            ...e,
            payheadName:
              e.payheadDisplayName && e.payheadDisplayName.trim()
                ? e.payheadDisplayName
                : e.payheadName,
          }));

        // Return modified monthData object
        return {
          Month:
            norMonths[+String(monthData.month).slice(4, 6) - 1] +
            ' ' +
            String(monthData.month).slice(0, 4),
          'Salary Scale': actualGross,
          'Total Days': totalDays,
          earningPayHead: earningPayHead,
          'Gross Salary': grossAmount,
          deductionPayHead: deductionPayHead,
          'Total Deduction': deductionAmount,
          extra_earningPayHead: extra_earningPayHead,
          'Total Salary': netPayAmount,
        };
      }
    });

    const data = data1.filter((e) => e !== undefined);

    const sumByKey = (array, key) => {
      return array.reduce((acc, obj) => {
        return acc + obj[key];
      }, 0);
    };

    // Extract all unique payhead names
    const payheadNames = Array.from(
      new Set(
        data.flatMap((item) =>
          item.earningPayHead
            .concat(item.deductionPayHead)
            .concat(item.extra_earningPayHead)
            .map((payhead) => payhead.payheadName)
        )
      )
    );

    // Initialize an object to hold the sum of each payhead
    const payheadSums = {};

    // Initialize an object to hold the summary object
    const summaryObject = {
      Month: 'Total',
      'Salary Scale': sumByKey(data, 'Salary Scale'),
      'Total Days': sumByKey(data, 'Total Days'),
      earningPayHead: [],
      'Gross Salary': sumByKey(data, 'Gross Salary'),
      deductionPayHead: [],
      'Total Deduction': sumByKey(data, 'Total Deduction'),
      extra_earningPayHead: [],
      'Total Salary': sumByKey(data, 'Total Salary'),
    };

    // Calculate the sum for each payhead
    payheadNames.forEach((payheadName) => {
      const earningAmountSum = sumByKey(
        data.flatMap((item) =>
          item.earningPayHead.filter(
            (payhead) =>
              payhead.payheadName === payheadName &&
              payhead.salaryFieldSrNo === 'A' &&
              payhead.considerIn != 'net'
          )
        ),
        'EmployeeSalaryAmount'
      );
      const deductionAmountSum = sumByKey(
        data.flatMap((item) =>
          item.deductionPayHead.filter(
            (payhead) =>
              payhead.payheadName === payheadName &&
              payhead.salaryFieldSrNo !== 'A'
          )
        ),
        'EmployeeSalaryAmount'
      );

      const extra_earningAmountSum = sumByKey(
        data.flatMap((item) =>
          item.extra_earningPayHead.filter(
            (payhead) =>
              payhead.payheadName === payheadName &&
              payhead.salaryFieldSrNo === 'A' &&
              payhead.considerIn == 'net'
          )
        ),
        'EmployeeSalaryAmount'
      );

      // Add the sums to the payheadSums object
      payheadSums[payheadName] = {
        earningAmountSum,
        deductionAmountSum,
        extra_earningAmountSum,
      };

      // Add the payhead to the summary object
      if (earningAmountSum !== 0) {
        summaryObject.earningPayHead.push({
          payheadName,

          EmployeeSalaryAmount: earningAmountSum,
        });
      }
      if (deductionAmountSum !== 0) {
        summaryObject.deductionPayHead.push({
          payheadName,

          EmployeeSalaryAmount: deductionAmountSum,
        });
      }

      if (extra_earningAmountSum !== 0) {
        summaryObject.extra_earningPayHead.push({
          payheadName,
          EmployeeSalaryAmount: extra_earningAmountSum,
        });
      }
    });

    // Push the summary object to the data array
    data.push(summaryObject);

    const finaldata = data.map((e) => {
      const object = {};
      object['Month'] = e['Month'];
      object['Salary Scale'] = e['Salary Scale'];
      object['Total Days'] = e['Total Days'];

      e.earningPayHead.forEach((ep) => {
        object[ep.payheadName] = ep.EmployeeSalaryAmount;
      });

      // object['Earning'] = earningPayHead
      object['Gross Salary'] = e['Gross Salary'];

      e.deductionPayHead.forEach((ep) => {
        object[ep.payheadName] = ep.EmployeeSalaryAmount;
      });
      // object['Deduction'] = deductionPayHead

      object['Total Deduction'] = e['Total Deduction'];
      // extra earning payhead
      e.extra_earningPayHead.forEach((ep) => {
        object[ep.payheadName] = ep.EmployeeSalaryAmount;
      });

      object['Total Salary'] = e['Total Salary'];

      return object;
    });

    if (Export) {
      const userData = await UserMaster.findOne({
        raw: true,
        where: {
          userMasterID: userMasterID,
        },
        include: [
          { model: EmployeeJoiningDetails, attributes: [] },
          { model: companyMaster, attributes: [] },
        ],
        attributes: [
          'displayName',
          [
            sequelize.col('employeeJoiningDetails.employeeCode'),
            'employeeCode',
          ],
          [sequelize.col('companyMaster.companyName'), 'companyName'],
          [sequelize.col('companyMaster.companyAddress'), 'companyAddress'],
        ],
      });

      function formatDate(date) {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${day}-${month}-${year}`;
      }

      function generateStartEndDate(startMonth, endMonth) {
        const startDate = new Date(
          parseInt(startMonth.substring(0, 4)),
          parseInt(startMonth.substring(4)) - 1,
          1
        );
        const endDate = new Date(
          parseInt(endMonth.substring(0, 4)),
          parseInt(endMonth.substring(4)),
          0
        );

        return {
          startDate: formatDate(startDate),
          endDate: formatDate(endDate),
        };
      }

      const { startDate, endDate } = generateStartEndDate(startMonth, endMonth);

      const tempData = { ...userData, startDate: startDate, endDate: endDate };

      if (Export == 'excel')
        return generateExcelForEmployeeWiseSalaryReport(
          data,
          tempData,
          'Employee Wise Salary Report',
          'xlsx',
          res
        );

      if (Export == 'pdf') {
        const headers = Object.keys(finaldata[finaldata.length - 1]);

        const finaldata2 = finaldata.map((e) => {
          const object = {};

          headers.forEach((ep) => {
            object[ep] = e[ep] ? e[ep] : '';
          });
          return object;
        });

        const pdfData = {
          tempData: tempData,
          headers: headers,
          finaldata: finaldata2,
        };

        const getTemplate1 = (type) => {
          const file = path.join(__dirname, `../html/${type}.html`);
          return file;
        };

        const filePath = await getTemplate1('employeeWiseSalaryReport');

        const file = await readFile(filePath);
        const template = Handlebars.compile(file);
        const html = template(pdfData);

        const browser = await puppeteer.launch({
          headless: 'new',
          args: ['--no-sandbox'],
        });
        const page = await browser.newPage();

        // Set the HTML content of the page
        await page.setContent(html);

        // Generate PDF
        const pdfBuffer = await page.pdf({
          format: 'A4', // Page format (A4 in this case)
          printBackground: true, // print background
          margin: { top: '10px', bottom: '10px' },
          landscape: true, // Set PDF to landscape mode
        });
        await browser.close();

        let base64path = Buffer.from(pdfBuffer).toString('base64');

        return res.status(200).json({
          status: 200,
          data: base64path,
        });
      }
    }

    return res.status(200).json({
      status: 200,
      data: finaldata,
    });
  } catch (error) {
    next(error);
  }
};

exports.form16Report = async (req, res, next) => {
  try {
    const { userMasterID, financialYear } = req.body;

    const currentFy_Year = String(await getCurrentFinancialYear(new Date()))
      .split('-')
      .join('');
    const selectedFy_Year = String(financialYear).split('-').join('');

    if (+currentFy_Year <= +selectedFy_Year)
      return res.status(200).json({
        status: 401,
        message: 'you can not select future financial year!',
      });

    const yearRange = financialYear.split('-');
    // const currentFinancialYear = yearRange[0];

    const fy_startDate = yearRange[0] + '-' + '04' + '-' + '01';
    const fy_endDate = yearRange[1] + '-' + '03' + '-' + '31';

    const userdata = await UserMaster.findOne({
      raw: true,
      where: {
        userMasterID: userMasterID,
        status: 1,
      },
      include: [
        {
          model: EmployeeJoiningDetails,
          where: {
            joiningDate: {
              [Sequelize.Op.lte]: new Date(fy_endDate),
            },
            [Sequelize.Op.or]: [
              {
                leavingDate: { [Sequelize.Op.gte]: new Date(fy_startDate) },
              },
              {
                leavingDate: { [Sequelize.Op.eq]: null },
              },
            ],
          },
          attributes: ['joiningDate', 'pancard', 'leavingDate'],
        },
      ],
    });

    if (!userdata)
      return res.status(200).json({
        status: 401,
        message: 'User not found!',
      });

    const [userAddress, companyData] = await Promise.all([
      UserAddress.findAll({
        raw: true,
        where: {
          userMasterID: userMasterID,
          // addressType: 'permanent',
          status: 1,
        },
        include: [
          {
            model: CityMaster,
            include: [
              {
                model: StateMaster,
                include: [
                  { model: CountryMaster, attributes: ['countryName'] },
                ],
                attributes: ['stateName'],
              },
            ],
            attributes: ['cityName'],
          },
        ],
      }),
      companyMasters.findOne({
        raw: true,
        where: {
          companyMasterID: userdata.companyMasterId,
          status: 1,
        },
        include: [{ model: CityMaster, attributes: ['cityName'] }],
      }),
    ]);

    const permanentUserAddress = userAddress.find(
      (e) => e.addressType == 'permanent'
    );

    const data = {};

    data['employeeName'] = userdata.displayName;

    const address =
      userAddress.length > 0
        ? permanentUserAddress
          ? permanentUserAddress
          : userAddress[0]
        : {};

    let fullAddress = '';

    if (address) {
      if (address.houseNumber) fullAddress += `${address.houseNumber},`;

      if (address.houseName) fullAddress += `${address.houseName},`;

      if (address.landmark) fullAddress += `${address.landmark},`;
      if (address.area) fullAddress += `${address.area},`;
      if (address['cityMaster.cityName'])
        fullAddress += `${address['cityMaster.cityName']},`;
      if (address['cityMaster.stateMaster.stateName'])
        fullAddress += `${address['cityMaster.stateMaster.stateName']},`;
      if (address['cityMaster.stateMaster.countryMaster.countryName'])
        fullAddress += `${address['cityMaster.stateMaster.countryMaster.countryName']}`;
      if (address.zipcode) fullAddress += ` ${address.zipcode}`;
    }

    data['employeeAddress'] = fullAddress;
    data['employeePANNo'] = userdata['employeeJoiningDetails.pancard'];

    const startdate =
      new Date(fy_startDate) <
      new Date(userdata['employeeJoiningDetails.joiningDate'])
        ? userdata['employeeJoiningDetails.joiningDate']
        : fy_startDate;

    data['startDate'] = startdate
      ? startdate.slice(8, 10) +
        '-' +
        norMonths[startdate.slice(5, 7) - 1] +
        '-' +
        startdate.slice(0, 4)
      : '';

    const enddate = userdata['employeeJoiningDetails.leavingDate']
      ? new Date(fy_endDate) >
        new Date(userdata['employeeJoiningDetails.leavingDate'])
        ? userdata['employeeJoiningDetails.leavingDate']
        : fy_endDate
      : fy_endDate;

    data['endDate'] = enddate
      ? enddate.slice(8, 10) +
        '-' +
        norMonths[enddate.slice(5, 7) - 1] +
        '-' +
        enddate.slice(0, 4)
      : '';

    data['companyName'] = companyData ? companyData.companyName : '';
    data['companyAddress'] = companyData ? companyData.companyAddress : '';
    data['companyMail'] = companyData ? companyData.companyEmail : '';
    data['companyOwnerName'] = companyData ? companyData.ownerName : '';
    data['companyOwnerFatherName'] = companyData
      ? companyData.ownerFatherName
      : '';
    data['companyCity'] = companyData ? companyData['cityMaster.cityName'] : '';
    data['companyPANNo'] = companyData ? companyData.panNumber : '';
    data['companyTANNo'] = companyData ? companyData.tanNumber : '';
    data['AssessmentYear'] = await getCurrentFinancialYear(new Date());

    const currentdate = asiaKolkataDateTime(new Date()).slice(0, 10);

    let date = new Date();
    date.setDate(date.getDate() - 1);

    let previousDaydate = asiaKolkataDateTime(date).slice(0, 10);

    data['currentDate'] = currentdate
      ? currentdate.slice(8, 10) +
        '-' +
        norMonths[currentdate.slice(5, 7) - 1] +
        '-' +
        currentdate.slice(0, 4)
      : '';

    data['previousDate'] = previousDaydate
      ? previousDaydate.slice(8, 10) +
        '-' +
        norMonths[previousDaydate.slice(5, 7) - 1] +
        '-' +
        previousDaydate.slice(0, 4)
      : '';

    const startMonth = startdate.slice(0, 4) + startdate.slice(5, 7);
    const endMonth = enddate.slice(0, 4) + enddate.slice(5, 7);

    const incometaxdata = await getIncomeTaxDataforForm16Report(
      userMasterID,
      financialYear,
      startMonth,
      endMonth,
      userdata.gender ? userdata.gender : 'Male'
    );

    const finalData = {
      ...data,
      ...incometaxdata,
      url: `${dotenv.parsed.APIURL}css/assets/form16HeaderImage.png`,
    };

    const getTemplate = () => {
      const file = path.join(__dirname, `../html/form16.html`);
      return file;
    };

    Handlebars.registerHelper({
      eq: (v1, v2) => v1 === v2,
      ne: (v1, v2) => v1 !== v2,
      lt: (v1, v2) => v1 < v2,
      gt: (v1, v2) => v1 > v2,
      lte: (v1, v2) => v1 <= v2,
      gte: (v1, v2) => v1 >= v2,
      and() {
        return Array.prototype.every.call(arguments, Boolean);
      },
      or() {
        return Array.prototype.slice.call(arguments, 0, -1).some(Boolean);
      },
    });

    const readFile = (name) => {
      return new Promise((resolve, reject) => {
        fs.readFile(name, 'utf-8', (err, result) => {
          if (err) {
            reject(err);
          } else {
            resolve(result);
          }
        });
      });
    };

    const filePath = getTemplate();

    const file = await readFile(filePath);
    const template = Handlebars.compile(file);
    const htmlContent = template(finalData);

    const browser = await puppeteer.launch({
      headless: 'new',
      args: ['--no-sandbox'],
      timeout: 120000,
    });

    const pdfPage = await browser.newPage();

    // Set the HTML content of the pdfPage
    await pdfPage.setContent(htmlContent);

    // Generate PDF
    const pdfBuffer = await pdfPage.pdf({
      format: 'A4', // pdfPage format (A4 in this case)
      printBackground: true, // print background
      timeout: 120000,
      // displayHeaderFooter: true, // display header and footer
      // footerTemplate: `
      // <div style="font-size: 12px; margin: 40px 0px 0px 350px; text-align: center;padding: 0px !important">
      //   <span>Page <span class="pageNumber"></span> of <span class="totalPages"></span></span>
      // </div>`, // footer with page number
    });

    await browser.close();

    let pdfBase64Path = Buffer.from(pdfBuffer).toString('base64');

    return res.status(200).json({
      // pdfBase64Path,
      message: message.usermessage.fetchMessage('Form 16'),
      data: pdfBase64Path,
      status: 200,
    });
  } catch (err) {
    next(err);
  }
};

