exports.shiftwiseattendancecount = async (req, res, next) => {
  try {
    const { companyMasterID, startdate, enddate, exportData } = req.query;

    const data = await attendanceTransaction.findAll({
      where: {
        '$shift.companyMasterID$': companyMasterID,
        AttendanceDate: {
          [Sequelize.Op.between]: [startdate, enddate],
        },
      },
      include: [
        {
          model: Shift,
          attributes: ['shiftName'],
        },
      ],
    });

    const attendanceCounts = data.reduce((acc, record) => {
      const date = record.AttendanceDate;
      const shiftName = record.shift.shiftName;

      if (!acc[shiftName]) {
        acc[shiftName] = {};
      }
      if (!acc[shiftName][date]) {
        acc[shiftName][date] = 0;
      }
      acc[shiftName][date] += 1;

      return acc;
    }, {});

    const dates = Array.from(
      new Set(data.map((record) => record.AttendanceDate))
    );

    const formatDate = (dateString) => {
      const date = new Date(dateString);
      const day = String(date.getDate()).padStart(2, '0');
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const year = date.getFullYear();
      return `${day}-${month}-${year}`;
    };

    const formattedDates = dates.map((date) => formatDate(date));

    const result = Object.keys(attendanceCounts).map((shiftName) => {
      const row = { 'Shift Name': shiftName };
      formattedDates.forEach((formattedDate) => {
        const originalDate = dates.find(
          (date) => formatDate(date) === formattedDate
        );
        row[formattedDate] = attendanceCounts[shiftName][originalDate] || 0;
      });
      return row;
    });

    if (exportData) {
      return await generateExcelDailyAttendanceCountDepartmentwise(
        result,
        dates,
        'daily-attendance-count',
        'xlsx',
        res
      );
    }

    return res.status(200).json({
      status: 200,
      message: 'Attendance counts fetched successfully',
      data: result,
      totalcount: result.length,
    });
  } catch (err) {
    next(err);
  }
};

exports.loanReport = async (req, res, next) => {
  try {
    const {
      companyMasterID,
      startdate,
      enddate,
      branchMasterID,
      userMasterID,
      limit,
      page,
      exportData,
    } = req.body;

    const paginationQuery = {};
    const condition = {
      status: 1,
      loanstatus: 1,
    };

    condition.companyMasterID = companyMasterID;

    if (!exportData && page && limit) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = +limit;
    }

    if (startdate && enddate) {
      condition.createdAt = {
        [Sequelize.Op.between]: [startdate, enddate],
      };
    }

    if (userMasterID && userMasterID.length > 0) {
      condition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };
    }

    const filterDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const { rows: data, count } = await LoanMaster.findAndCountAll({
      where: condition,
      ...paginationQuery,
      distinct: true,
      include: [
        {
          model: LoanTransaction,
        },
        {
          model: LoanAdvance,
        },
        {
          model: UserMaster,
          attributes: ['displayName', 'userNumber'],
          include: [
            {
              model: EmployeeDesignation,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['designationID'],
              include: [
                {
                  model: Designation,
                  as: 'designation',
                  attributes: ['designationName'],
                },
              ],
            },
            {
              model: EmployeeDepartment,
              where: {
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['departmentID'],
              include: [
                {
                  model: Department,
                  as: 'department',
                  attributes: ['departmentName'],
                },
              ],
            },
            {
              model: EmployeeBranch,
              where: {
                // ...(branchMasterID && { branchID: branchMasterID }),
                status: 1,
                applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
                [Sequelize.Op.or]: [
                  { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },
              required: false,
              attributes: ['branchID'],
              include: [
                {
                  model: BranchMaster,
                  as: 'branchMaster',
                  attributes: ['branchName'],
                },
              ],
            },
            {
              model: EmployeeJoiningDetails,
              attributes: ['employeeCode'],
            },
          ],
          required: true,
        },
      ],
    });

    const finalData = data.map((e) => {
      const employeeJoiningDetails = e.userMaster
        ? e.userMaster.employeeJoiningDetails[0]
        : {} || {};
      const employeeBranches = e.userMaster
        ? e.userMaster.employeeBranches[0]
        : {} || {};
      const employeeDesignations = e.userMaster
        ? e.userMaster.employeeDesignations[0]
        : {} || {};
      const employeeDepartments = e.userMaster
        ? e.userMaster.employeeDepartments[0]
        : {} || {};
      let remainingAmount = e.LoanAmount;
      let paidAmount = 0;
      let paidEmi = 0;

      const advance = e.loanAdvances.reduce((acc, obj) => acc + +obj.Amount, 0);

      e.loanTransactions.forEach((transaction) => {
        if (transaction.RefrenceId) {
          remainingAmount -= transaction.EMIAmount;
          paidAmount += transaction.EMIAmount;
          paidEmi++;
        }
      });

      return {
        'Employee Code': employeeJoiningDetails
          ? employeeJoiningDetails.employeeCode
          : '',
        Name: e.userMaster ? e.userMaster.displayName : '',
        Number: e.userMaster ? e.userMaster.userNumber : '',
        'Branch Name':
          employeeBranches && employeeBranches.branchMaster
            ? employeeBranches.branchMaster.branchName
            : '',
        'Department Name':
          employeeDepartments && employeeDepartments.department
            ? employeeDepartments.department.departmentName
            : '',
        'Designation Name':
          employeeDesignations && employeeDesignations.designation
            ? employeeDesignations.designation.designationName
            : '',
        'Loan Amount': e.LoanAmount,
        'Loan Advance': +advance,
        'Remaining Amount': +remainingAmount - +advance,
        'Paid Amount': +paidAmount + +advance,
        'Paid EMI': paidEmi,
        'Loan Remarks': e.LoanRemark,
        'Emi Months': e.EMIMonths,
        'Start Month': e.startMonth
          ? month_dict[String(e.startMonth).slice(4, 6)] +
            ' - ' +
            String(e.startMonth).slice(0, 4)
          : '',
      };
    });

    if (exportData) {
      return await generateExcel(finalData, 'loan-Report', 'xlsx', res);
    }

    return res.status(200).json({
      status: 200,
      message: 'Data fetched successfully',
      data: finalData,
      totalcount: count,
    });
  } catch (err) {
    next(err);
  }
};

exports.shiftDepartmentWiseDailyAttendanceCount = async (req, res, next) => {
  try {
    const { companyMasterID, startdate, enddate, exportData } = req.query;

    const data = await attendanceTransaction.findAll({
      where: {
        '$shift.companyMasterID$': companyMasterID,
        AttendanceDate: {
          [Sequelize.Op.between]: [startdate, enddate],
        },
      },
      include: [
        {
          model: Shift,
          attributes: ['shiftName'],
        },
        {
          model: Department,
          attributes: ['departmentName'],
        },
      ],
    });

    const attendanceCounts = data.reduce((acc, record) => {
      const date = record.AttendanceDate;
      const shiftName = record.shift.shiftName;
      const departmentName = record.department
        ? record.department.departmentName
        : '';

      if (!acc[shiftName]) {
        acc[shiftName] = {};
      }
      if (!acc[shiftName][departmentName]) {
        acc[shiftName][departmentName] = {};
      }
      if (!acc[shiftName][departmentName][date]) {
        acc[shiftName][departmentName][date] = 0;
      }
      acc[shiftName][departmentName][date] += 1;

      return acc;
    }, {});

    const dates = Array.from(
      new Set(data.map((record) => record.AttendanceDate))
    );

    const formatDate = (dateString) => {
      const date = new Date(dateString);
      const day = String(date.getDate()).padStart(2, '0');
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const year = date.getFullYear();
      return `${day}-${month}-${year}`;
    };

    const formattedDates = dates.map((date) => formatDate(date));

    if (exportData) {
      const exportResult = Object.keys(attendanceCounts).map((shiftName) => {
        const shiftRow = { 'Shift Name': shiftName };
        Object.keys(attendanceCounts[shiftName]).forEach((departmentName) => {
          const departmentRow = { 'Department Name': departmentName };
          formattedDates.forEach((formattedDate) => {
            const originalDate = dates.find(
              (date) => formatDate(date) === formattedDate
            );
            departmentRow[formattedDate] =
              attendanceCounts[shiftName][departmentName][originalDate] || 0;
          });
          shiftRow[departmentName] = departmentRow;
        });
        return shiftRow;
      });

      return await generateExcelDepartmentWisepunchinoutcountreport(
        exportResult,
        dates,
        'Shift-DepartmentWise-Daily-Attendance-Count-Report.xlsx',
        'xlsx',
        res
      );
      // return res.status(200).json({
      //   status: 200,
      //   data: exportResult,
      //   totalcount: result.length,
      // });
    }

    const result = [];
    Object.keys(attendanceCounts).forEach((shiftName) => {
      Object.keys(attendanceCounts[shiftName]).forEach((departmentName) => {
        const departmentRow = {
          'Shift Name': shiftName,
          'Department Name': departmentName,
        };

        formattedDates.forEach((formattedDate) => {
          const originalDate = dates.find(
            (date) => formatDate(date) === formattedDate
          );
          departmentRow[formattedDate] =
            attendanceCounts[shiftName][departmentName][originalDate] || 0;
        });

        result.push(departmentRow);
      });
    });

    return res.status(200).json({
      status: 200,
      data: result,
      totalcount: result.length,
    });
  } catch (err) {
    next(err);
  }
};

