exports.attendanceRegister3 = async (req, res, next) => {
  try {
    const { userMasterID, startDate, endDate } = req.body;

    const condition = {
      userMasterID: {
        [Sequelize.Op.in]: userMasterID,
      },
      AttendanceDate: {
        [Sequelize.Op.between]: [startDate, endDate],
      },
    };

    const totalDays = getDaysFromDates(startDate, endDate);

    const filterDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const datesArray = await getDatesFromDateRange(
      new Date(startDate),
      new Date(endDate)
    );

    const userData = await UserMaster.findAll({
      where: {
        userMasterID: userMasterID,
      },
      attributes: [
        'displayName',
        'userNumber',
        'userMasterID',
        'companyMasterId',
      ],
      include: [
        {
          required: false,
          model: attendanceTransaction,
          where: condition,
          include: [
            {
              required: false,
              model: overTimeCalculation,
            },
            {
              model: Shift,
              attributes: ['shiftName'],
            },
          ],
        },
        {
          required: false,
          model: EmployeeDesignation,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          required: false,

          model: EmployeeDepartment,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          required: false,

          model: EmployeeBranch,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date(filterDate) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(filterDate) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        },
        {
          required: false,

          model: EmployeeJoiningDetails,
          attributes: ['employeeCode'],
        },
        {
          required: false,
          model: weekoffHolidayTran,
          where: {
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
          },
        },
      ],
      order: [['displayName', 'ASC']],
    });

    const finalData = [];

    for (const userDetails of userData) {
      let totaldeductedHrs = 0;
      let totalOTHrs = 0;
      let totalActaulInHrs = 0;
      let totalWithoutOTMinutes = 0;
      let totalRemainigHrs = 0;
      let totallatePenaltyMinutes = 0;
      let totalearlyPenaltyMinutes = 0;
      let totalLateBy = 0;
      let totalEarlyBy = 0;
      let totalOutBreakTime = 0;

      for (const date of datesArray) {
        let attendanceStatus = 'A';
        let deductedHrs = 0;
        const finalDate = date.toISOString().slice(0, 10);

        const att =
          userDetails.attendanceTransactions &&
          userDetails.attendanceTransactions.length > 0
            ? userDetails.attendanceTransactions.find(
                (e) => e.AttendanceDate == finalDate
              )
            : null;
        const findWeekOff =
          userDetails.weekoffHolidayTrans &&
          userDetails.weekoffHolidayTrans.length > 0
            ? userDetails.weekoffHolidayTrans.find(
                (e) => e.date == finalDate && e.tableName == 'weekoff'
              )
            : null;

        const findHoliday =
          userDetails.weekoffHolidayTrans &&
          userDetails.weekoffHolidayTrans.length > 0
            ? userDetails.weekoffHolidayTrans.find(
                (e) => e.date == finalDate && e.tableName == 'holiday'
              )
            : null;

        const latePenaltyMinutes =
          att && att.PanaltyDeduction == 'min' ? +att.Panalty : 0;
        const earlyPenaltyMinutes =
          att && att.goEarlyPanaltyDeduction == 'min' ? +att.goEarlyPanalty : 0;

        if (att)
          deductedHrs =
            +att.OutHrs +
            +att.LateBy +
            +att.EarlyBy +
            +latePenaltyMinutes +
            +earlyPenaltyMinutes;

        totaldeductedHrs += deductedHrs;
        totalOutBreakTime += att ? +att.OutHrs : 0;
        const otHrs =
          att &&
          att.OverTimeCalculations &&
          att.OverTimeCalculations.length > 0 &&
          att.OverTimeCalculations[0].AuthorizationRequired != 4
            ? att.OverTimeCalculations[0].AuthorizationRequired == 3
              ? +att.OverTimeCalculations[0].UpdateOverTimeHourAndMin
              : +att.OverTimeCalculations[0].OverTimeHourAndMin
            : 0;
        totalOTHrs += +otHrs;

        const Actual_OTHrs =
          (att && att.OverTimeCalculations && att.OverTimeCalculations.length) >
          0
            ? att.OverTimeCalculations[0].OverTimeHourAndMin
            : 0;

        const actaulInHrs =
          att && att.roundOffMinutes ? +att.roundOffMinutes : 0;
        totalActaulInHrs += +actaulInHrs;

        let withoutOTMinutes = 0;

        if (+userDetails.companyMasterId == 29) {
          //for Sumitek Natraj Machinery Private Limited

          withoutOTMinutes =
            att && +att.InHrs - +Actual_OTHrs > 0
              ? +att.InHrs - +Actual_OTHrs
              : 0;

          totalWithoutOTMinutes += +withoutOTMinutes;
        } else {
          withoutOTMinutes =
            att && att.withoutOtMinutes ? +att.withoutOtMinutes : 0;
          totalWithoutOTMinutes += +withoutOTMinutes;
        }
        const remainigHrs =
          att && +att.Shifthrs * 60 - +actaulInHrs > 0
            ? +att.Shifthrs * 60 - +actaulInHrs
            : 0;
        totalRemainigHrs += +remainigHrs;
        totallatePenaltyMinutes += +latePenaltyMinutes;
        totalearlyPenaltyMinutes += +earlyPenaltyMinutes;
        totalLateBy += att ? +att.LateBy : 0;
        totalEarlyBy += att ? +att.EarlyBy : 0;

        attendanceStatus =
          att && +att.fulldayhalfday > 0
            ? +att.fulldayhalfday == 1
              ? 'P'
              : 'HFD'
            : 'A';
        if (att && att.OutDateTime == null) {
          attendanceStatus = `Miss Punch`;
        }
        if (
          att &&
          att.OutDateTime == null &&
          att.InDatetime != null &&
          att.AttendanceDate == filterDate
        ) {
          attendanceStatus = `P`;
        }
        if (findWeekOff) {
          if (attendanceStatus != 'A') {
            attendanceStatus = `${attendanceStatus} + Weekoff`;
          } else {
            attendanceStatus = 'Weekoff';
          }
        } else if (findHoliday) {
          if (attendanceStatus != 'A') {
            attendanceStatus = `${attendanceStatus} + Holiday`;
          } else {
            attendanceStatus = 'Holiday';
          }
        }
        finalData.push({
          'Employee Code':
            userDetails.employeeJoiningDetails &&
            userDetails.employeeJoiningDetails.length > 0
              ? userDetails.employeeJoiningDetails[0].employeeCode
              : '',
          'Employee Name': userDetails.displayName,
          Number: userDetails.userNumber,
          Branch:
            userDetails.employeeBranches &&
            userDetails.employeeBranches.length > 0 &&
            userDetails.employeeBranches[0].branchMaster
              ? userDetails.employeeBranches[0].branchMaster.branchName
              : '',
          Department:
            userDetails.employeeDepartments &&
            userDetails.employeeDepartments.length > 0 &&
            userDetails.employeeDepartments[0].department
              ? userDetails.employeeDepartments[0].department.departmentName
              : '',
          Designation:
            userDetails.employeeDesignations &&
            userDetails.employeeDesignations.length > 0 &&
            userDetails.employeeDesignations[0].designation
              ? userDetails.employeeDesignations[0].designation.designationName
              : '',
          Shift: att ? att.shift.shiftName : '',
          'Attendance Date': finalDate.split('-').reverse().join('-'),
          'Actual In Time': att ? toGetFormateddate(att.InDatetime) : '',
          'Actual Out Time': att ? toGetFormateddate(att.OutDateTime) : '',
          'Out/Break Hours': att ? minutesToHoursMinutes(+att.OutHrs) : '',
          'Late Penalty Hours': minutesToHoursMinutes(+latePenaltyMinutes),
          'Early Penalty Hours': minutesToHoursMinutes(+earlyPenaltyMinutes),
          'Late In Hours': att ? minutesToHoursMinutes(+att.LateBy) : '',
          'Early Go Hours': att ? minutesToHoursMinutes(+att.EarlyBy) : '',
          'Total Hours To Be Deducted': minutesToHoursMinutes(+deductedHrs),
          'Actual In Hours': att ? minutesToHoursMinutes(+actaulInHrs) : '',
          'Without OT Minutes': att
            ? minutesToHoursMinutes(+withoutOTMinutes)
            : '',
          'Remaining Hours': att ? minutesToHoursMinutes(+remainigHrs) : '',
          'OT Hours': minutesToHoursMinutes(+otHrs),
          'Present/Absent': attendanceStatus,
        });
      }

      const weeklyAverageMin = totalDays
        ? Math.round((+totalActaulInHrs * 7) / totalDays)
        : 0;

      finalData.push(
        buildRow(
          'Total',
          minutesToHoursMinutes(totalOutBreakTime),
          minutesToHoursMinutes(totallatePenaltyMinutes),
          minutesToHoursMinutes(totalearlyPenaltyMinutes),
          minutesToHoursMinutes(totalLateBy),
          minutesToHoursMinutes(totalEarlyBy),
          minutesToHoursMinutes(totaldeductedHrs),
          minutesToHoursMinutes(totalActaulInHrs),
          minutesToHoursMinutes(totalWithoutOTMinutes),
          minutesToHoursMinutes(totalRemainigHrs),
          minutesToHoursMinutes(totalOTHrs)
        ),
        buildRow(),
        buildRow(
          '',
          '',
          '',
          '',
          '',
          '',
          '',
          '',
          '',
          '',
          'Weekly Average Hours',
          minutesToHoursMinutes(weeklyAverageMin)
        ),
        buildRow(),
        buildRow()
      );
    }

    return await generateExcel(finalData, 'Attendance Register-3', 'xlsx', res);
  } catch (error) {
    next(error);
  }
};

function getRandomNumber(max) {
  return Math.floor(Math.random() * (max + 1));
}

// Api--------------------------------------

exports.attendanceReport4 = async (req, res, next) => {
  try {
    let { userMasterID, YearMM } = await req.body;

    if (!userMasterID || !YearMM)
      return res.status(200).json({
        status: 401,
        message: 'Invalid parameters!',
        data: [],
      });

    const currentdate = asiaKolkataDateTime(new Date()).slice(0, 10);
    const [year, month] = YearMM.split('-');

    // Start date -> First day of the month
    const calendarstartdate = moment(YearMM, 'YYYY-MM')
      .startOf('month')
      .format('YYYY-MM-DD');
    const calendarenddate = moment(YearMM, 'YYYY-MM')
      .endOf('month')
      .format('YYYY-MM-DD');

    const yearMonth = String(year) + String(month);
    const userData1 = UserMaster.findAll({
      where: {
        userMasterID,
        // status: 1,
      },
      order: [['displayName', 'ASC']],
      include: [
        {
          model: EmployeeJoiningDetails,
          attributes: ['employeeCode'],
          required: true,
        },
        {
          model: EmployeeBranch,
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(calendarenddate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: {
                  [Sequelize.Op.gte]: new Date(calendarenddate),
                },
              },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        },
        {
          required: false,
          model: EmployeeDesignation,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date(calendarenddate) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(calendarenddate) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          required: false,
          model: EmployeeDepartment,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date(calendarenddate) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(calendarenddate) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        { model: companyMaster, attributes: ['companyName'], required: true },
        {
          model: hrLeaveMonthlyTrans,
          required: false,
          where: { AttnYearMon: yearMonth },
          attributes: ['userMasterID', 'LeaveTranId', 'AttnVal'],
          include: [
            {
              model: hrLeaveTypes,
              where: { LeaveID: { [Sequelize.Op.notIn]: [29, 30, 31, 32] } },
              attributes: ['LeaveID'],
              include: [
                {
                  model: HrLeaveMaster,
                  as: 'LeaveMaster',
                  attributes: ['LeaveName'],
                },
              ],
            },
          ],
        },
        {
          separate: true,
          required: false,
          model: EmployeeAttendancePolicy,
          where: {
            status: 1,
            [Sequelize.Op.or]: [
              {
                startDate: {
                  [Sequelize.Op.between]: [
                    calendarstartdate,
                    calendarstartdate,
                  ],
                },
              },
              {
                endDate: {
                  [Sequelize.Op.between]: [
                    calendarstartdate,
                    calendarstartdate,
                  ],
                },
              },
              {
                [Sequelize.Op.and]: [
                  { startDate: { [Sequelize.Op.lte]: calendarstartdate } },
                  {
                    [Sequelize.Op.or]: [
                      {
                        endDate: {
                          [Sequelize.Op.gte]: calendarstartdate,
                        },
                      },
                      { endDate: { [Sequelize.Op.eq]: null } },
                    ],
                  },
                ],
              },
            ],
          },
          attributes: ['attendancePolicyID', 'startDate', 'endDate'],
          include: [
            {
              model: AttendancePolicy,
              as: 'attendancePolicy',
              attributes: ['WHPHPriority'],
            },
          ],
        },
      ],
      attributes: ['userMasterID', 'displayName', 'companyMasterId'],
    });
    const attendancedata1 = attendanceTransaction.findAll({
      where: {
        userMasterID,
        AttendanceDate: {
          [Sequelize.Op.between]: [calendarstartdate, calendarenddate],
        },
      },
      include: [
        {
          model: Shift,
          attributes: ['shiftName'],
        },
        {
          separate: true,
          required: false,
          model: UserShortLeave,
          where: {
            authorizationStatus: 3,
          },
        },
      ],
      attributes: [
        'userMasterID',
        'InDatetime',
        'OutDateTime',
        'AttendanceDate',
        'Shift',
        'fulldayhalfday',
        'Shifthrs',
        'ShiftoutTime',
        'ShiftIntime',
      ],
      order: [['AttendanceDate', 'ASC']],
    });
    const weekholidaydata1 = weekoffHolidayTran.findAll({
      where: {
        userMasterID,
        date: {
          [Sequelize.Op.between]: [calendarstartdate, calendarenddate],
        },
        [Sequelize.Op.or]: [
          { optionalHoliday: false },
          { optionalHoliday: null },
        ],
      },
      attributes: [
        'userMasterID',
        'date',
        'optionalHoliday',
        'tableName',
        'value',
      ],
      order: [['date', 'ASC']],
    });
    const userleaveData1 = UserLeave.findAll({
      where: {
        userMasterID,
        [Sequelize.Op.or]: [
          {
            FromDate: {
              [Sequelize.Op.between]: [calendarstartdate, calendarenddate],
            },
          },
          {
            ToDate: {
              [Sequelize.Op.between]: [calendarstartdate, calendarenddate],
            },
          },
        ],
        status: 1,
      },
      include: [
        {
          separate: true,
          required: false,
          model: UserLeaveTransaction,
          include: [
            {
              model: hrLeaveTypes,
              attributes: ['LeaveID'],
              include: [{ model: HrLeaveMaster, as: 'LeaveMaster' }],
            },
          ],
          attributes: ['LeaveTranId', 'days', 'date', 'status'],
        },
      ],
      attributes: [
        'LeaveTranId',
        'userMasterID',
        'FromDate',
        'ToDate',
        'authorizationStatus',
      ],
    });

    const [allUserData, attendancedata, weekholidaydata, userleaveData] =
      await Promise.all([
        userData1,
        attendancedata1,
        weekholidaydata1,
        userleaveData1,
      ]);

    const employeeAttendanceSummary = [],
      allUser_HrleaveData = [],
      hrLeaveHeader = [];

    for (let userData of allUserData) {
      const empJoining = userData.employeeJoiningDetails[0];
      const company = userData.companyMaster.companyName;
      const branch =
        (userData.employeeBranches && userData.employeeBranches.length) > 0
          ? userData.employeeBranches[0].branchMaster
            ? userData.employeeBranches[0].branchMaster.branchName
            : ''
          : '';
      const department =
        (userData.employeeDepartments && userData.employeeDepartments.length) >
        0
          ? userData.employeeDepartments[0].department
            ? userData.employeeDepartments[0].department.departmentName
            : ''
          : '';
      const designation =
        (userData.employeeDesignations &&
          userData.employeeDesignations.length) > 0
          ? userData.employeeDesignations[0].designation
            ? userData.employeeDesignations[0].designation.designationName
            : ''
          : '';

      const userLeave = userleaveData.filter((leave) => {
        return leave.userMasterID == userData.userMasterID;
      });

      const userWeekOffData = weekholidaydata.filter((att) => {
        return userData.userMasterID == att.userMasterID;
      });

      const userAttendnaceData = attendancedata.filter((att) => {
        return att.userMasterID === userData.userMasterID;
      });

      const userAttendancePolicy = userData.employeeAttendancePolicies || [];
      if (empJoining) {
        let presentCount = 0;
        let missPunChCount = 0;
        let absentCount = 0;
        let leaveCount = 0;
        let lcegCount = 0;
        let halfDayCount = 0;
        let weekOffCount = 0;
        let holidayCount = 0;
        const finalAttendanceData = [];
        let monthStartDate = new Date(calendarstartdate);
        let monthEndDate = new Date(calendarenddate);
        while (monthStartDate <= monthEndDate) {
          const dt = monthStartDate.toISOString().slice(0, 10);
          const findDateWiseAttendancePolicy =
            userAttendancePolicy && userAttendancePolicy.length
              ? userAttendancePolicy.find(
                  (e) =>
                    e.startDate <= new Date(dt) &&
                    (e.endDate >= new Date(dt) || e.endDate == null)
                )?.userAttendancePolicy
              : null;
          const userleaveDateWise = userLeave.filter((leave) => {
            return (
              new Date(leave.FromDate) <= new Date(dt) &&
              new Date(leave.ToDate) >= new Date(dt)
            );
          });

          // Pending Leave
          const userLeaveRequest = userleaveDateWise
            ? userleaveDateWise.find(
                (e) =>
                  e.authorizationStatus == 0 ||
                  e.authorizationStatus == 1 ||
                  e.authorizationStatus == 2
              )
            : null;

          // Approved Leave
          const approveLeave = [];

          if (userleaveDateWise && userleaveDateWise.length > 0) {
            for (const leave of userleaveDateWise) {
              for (const leavetrans of leave.userLeaveTransactions) {
                if (
                  new Date(leavetrans.date).getTime() ==
                    new Date(dt).getTime() &&
                  leavetrans.status == 1
                )
                  approveLeave.push(leavetrans);
              }
            }
          }

          // weekoff data
          const weekOffData =
            userWeekOffData && userWeekOffData.length > 0
              ? userWeekOffData.filter((att) => {
                  return (
                    new Date(att.date).getTime() === new Date(dt).getTime()
                  );
                })
              : null;

          const dateWiseAttendaceData = userAttendnaceData.find((att) => {
            return att.AttendanceDate == dt;
          });

          let InDatetime = '';
          let OutDateTime = '';
          if (dateWiseAttendaceData) {
            if (dateWiseAttendaceData.InDatetime) {
              dateWiseAttendaceData.InDatetime = new Date(
                dateWiseAttendaceData.InDatetime
              ); // Create a Date object
              const hours = dateWiseAttendaceData.InDatetime.getHours()
                .toString()
                .padStart(2, '0'); // Get hours in 24-hour format
              const minutes = dateWiseAttendaceData.InDatetime.getMinutes()
                .toString()
                .padStart(2, '0'); // Get minutes
              InDatetime = `${hours}:${minutes}`;
            }

            if (dateWiseAttendaceData.OutDateTime) {
              let finalPuchOutTime = new Date(
                dateWiseAttendaceData.OutDateTime
              );

              const hours = finalPuchOutTime
                .getHours()
                .toString()
                .padStart(2, '0'); // Get hours in 24-hour format
              const minutes = finalPuchOutTime
                .getMinutes()
                .toString()
                .padStart(2, '0'); // Get minutes
              OutDateTime = `${hours}:${minutes}`;
            }
          }
          const weekoffDataToPush = (date, title) => {
            finalAttendanceData.push({
              inTime: InDatetime,
              outTime: OutDateTime,
              date: new Date(date).getDate(),
              title,
            });
          };

          if (dt <= currentdate) {
            if (dateWiseAttendaceData) {
              // Check Shift
              let tempTitle =
                dateWiseAttendaceData.fulldayhalfday == 1
                  ? 'P'
                  : dateWiseAttendaceData.fulldayhalfday == 0.5
                    ? 'HFD'
                    : dateWiseAttendaceData.fulldayhalfday == 0
                      ? 'A'
                      : currentdate == dateWiseAttendaceData.AttendanceDate
                        ? 'P'
                        : 'A';

              if (
                dateWiseAttendaceData.OutDateTime == null &&
                dateWiseAttendaceData.InDatetime
              )
                tempTitle = 'MP';

              if (dateWiseAttendaceData.latePenaltyMinutes)
                tempTitle = tempTitle + '+LC';
              if (dateWiseAttendaceData.earlyPenaltyMinutes)
                tempTitle = tempTitle + '+EG';

              if (dateWiseAttendaceData.PanaltyDeduction)
                tempTitle = tempTitle + '+LC';
              if (dateWiseAttendaceData.goEarlyPanaltyDeduction)
                tempTitle = tempTitle + '+EG';

              weekoffDataToPush(
                dateWiseAttendaceData.AttendanceDate,
                tempTitle
              );

              if (userLeaveRequest) {
                weekoffDataToPush(dt, 'Leave');
              } else {
                if (approveLeave.length > 0) {
                  for (let i = 0; i < approveLeave.length; i++) {
                    weekoffDataToPush(
                      dt,
                      approveLeave[i].hrLeaveType.LeaveMaster.LeaveName
                    );
                  }
                }
              }

              if (weekOffData && weekOffData.length) {
                let title = '';
                if (weekOffData.length > 1) {
                  if (findDateWiseAttendancePolicy) {
                    title =
                      findDateWiseAttendancePolicy.WHPHPriority == 'PH'
                        ? 'HD'
                        : 'WO';
                  } else {
                    title = weekOffData[0].optionalHoliday
                      ? 'OH'
                      : weekOffData[0].tableName === 'weekoff'
                        ? 'WO'
                        : 'HD';
                  }
                } else {
                  title = weekOffData[0].optionalHoliday
                    ? 'OH'
                    : weekOffData[0].tableName === 'weekoff'
                      ? 'WO'
                      : 'HD';
                }
                weekoffDataToPush(dt, title);
              }
            } else {
              // Leave Request
              if (userLeaveRequest) {
                weekoffDataToPush(dt, 'Leave');
                if (weekOffData && weekOffData.length) {
                  let title = '';
                  if (weekOffData.length > 1) {
                    if (findDateWiseAttendancePolicy) {
                      title =
                        findDateWiseAttendancePolicy.WHPHPriority == 'PH'
                          ? 'HD'
                          : 'WO';
                    } else {
                      if (
                        +userLeaveRequest?.LeaveDays <= 0.5 &&
                        weekOffData.value == 0.5
                      ) {
                        title = weekOffData[0].optionalHoliday
                          ? 'OH'
                          : weekOffData[0].tableName === 'weekoff'
                            ? 'WO'
                            : 'HD';
                      }
                    }
                  } else {
                    if (
                      +userLeaveRequest?.LeaveDays <= 0.5 &&
                      weekOffData.value == 0.5
                    ) {
                      title = weekOffData[0].optionalHoliday
                        ? 'OH'
                        : weekOffData[0].tableName === 'weekoff'
                          ? 'WO'
                          : 'HD';
                    }
                  }
                  weekoffDataToPush(dt, title);
                }
              } else {
                if (approveLeave.length > 0) {
                  for (let i = 0; i < approveLeave.length; i++) {
                    weekoffDataToPush(
                      dt,
                      approveLeave[i].hrLeaveType.LeaveMaster.LeaveName
                    );
                  }
                  if (weekOffData && weekOffData.length) {
                    let title = '';
                    if (weekOffData.length > 1) {
                      if (findDateWiseAttendancePolicy) {
                        title =
                          findDateWiseAttendancePolicy.WHPHPriority == 'PH'
                            ? 'HD'
                            : 'WO';
                      } else {
                        if (
                          +approveLeave.reduce(
                            (acc, obj) => acc + +obj.days,
                            0
                          ) <= 0.5 &&
                          weekOffData.value == 0.5
                        ) {
                          title = weekOffData[0].optionalHoliday
                            ? 'OH'
                            : weekOffData[0].tableName === 'weekoff'
                              ? 'WO'
                              : 'HD';
                        }
                      }
                    } else {
                      if (
                        +approveLeave.reduce(
                          (acc, obj) => acc + +obj.days,
                          0
                        ) <= 0.5 &&
                        weekOffData.value == 0.5
                      ) {
                        title = weekOffData[0].optionalHoliday
                          ? 'OH'
                          : weekOffData[0].tableName === 'weekoff'
                            ? 'WO'
                            : 'HD';
                      }
                    }
                    weekoffDataToPush(dt, title);
                  }
                } else {
                  if (weekOffData && weekOffData.length) {
                    let title = '';
                    if (weekOffData.length > 1) {
                      if (findDateWiseAttendancePolicy) {
                        title =
                          findDateWiseAttendancePolicy.WHPHPriority == 'PH'
                            ? 'HD'
                            : 'WO';
                      } else {
                        title = weekOffData[0].optionalHoliday
                          ? 'OH'
                          : weekOffData[0].tableName === 'weekoff'
                            ? 'WO'
                            : 'HD';
                      }
                    } else {
                      title = weekOffData[0].optionalHoliday
                        ? 'OH'
                        : weekOffData[0].tableName === 'weekoff'
                          ? 'WO'
                          : 'HD';
                    }
                    weekoffDataToPush(dt, title);
                  } else {
                    // if Absent
                    weekoffDataToPush(dt, 'A');
                  }
                }
              }
            }
          } else {
            // Leave Request
            if (userLeaveRequest) {
              weekoffDataToPush(dt, 'Leave');
            } else {
              if (approveLeave.length > 0) {
                for (let i = 0; i < approveLeave.length; i++) {
                  weekoffDataToPush(
                    dt,
                    approveLeave[i].hrLeaveType.LeaveMaster.LeaveName
                  );
                }
              } else {
                if (weekOffData) {
                  const title = weekOffData.optionalHoliday
                    ? 'OH'
                    : weekOffData.tableName === 'weekoff'
                      ? 'WO'
                      : 'HD';

                  weekoffDataToPush(dt, title);
                } else {
                  weekoffDataToPush(dt, 'A');
                }
              }
            }
          }
          monthStartDate = new Date(
            monthStartDate.setDate(monthStartDate.getDate() + 1)
          );

          const hrleaveData = Array.isArray(userData.hrLeaveMonthlyTrans)
            ? [...userData.hrLeaveMonthlyTrans].sort(
                (a, b) => a.LeaveTranId - b.LeaveTranId
              )
            : [];
          const allHrLeaveNames = hrleaveData.map(
            (e) => e.hrLeaveType.LeaveMaster.LeaveName
          );

          allHrLeaveNames.forEach((value) => {
            if (!hrLeaveHeader.includes(value)) {
              hrLeaveHeader.push(value);
            }
          });

          const obj = {};

          hrleaveData.forEach((e) => {
            obj[e.hrLeaveType.LeaveMaster.LeaveName] = e.AttnVal;
          });

          allUser_HrleaveData.push(obj);
        }

        const lastEntries = Object.values(
          finalAttendanceData.reduce((acc, current) => {
            const prevEntry = acc[current.date];
            if (prevEntry) {
              acc[current.date] = {
                date: current.date,
                inTime: prevEntry.inTime || current.inTime,
                outTime: prevEntry.outTime || current.outTime,
                title: acc[current.date].title + `+${current.title}`,
              };
            } else {
              acc[current.date] = current;
            }

            return acc;
          }, {})
        );
        lastEntries.forEach((entry) => {
          const tempTitle = entry.title;

          if (
            tempTitle === 'P' ||
            tempTitle === 'P+LC' ||
            tempTitle === 'P+EG' ||
            tempTitle === 'P+LC+EG'
          ) {
            presentCount++;
          } else if (tempTitle === 'MP') {
            missPunChCount++;
          } else if (
            tempTitle === 'HFD' ||
            tempTitle === 'HFD+LC' ||
            tempTitle === 'HFD+EG' ||
            tempTitle === 'HFD+LC+EG'
          ) {
            halfDayCount++;
          } else if (
            tempTitle === 'WO' ||
            tempTitle === 'P+WO' ||
            tempTitle === 'HFD+WO' ||
            tempTitle === 'A+WO' ||
            tempTitle === 'MP+WO'
          ) {
            weekOffCount++;
          } else if (
            tempTitle === 'HD' ||
            tempTitle === 'P+OH' ||
            tempTitle === 'P+HD' ||
            tempTitle === 'HFD+HD' ||
            tempTitle === 'A+HD' ||
            tempTitle === 'HFD+OH' ||
            tempTitle === 'A+OH' ||
            tempTitle === 'MP+HD'
          ) {
            holidayCount++;
          } else if (tempTitle === 'A') {
            absentCount++;
          } else {
            leaveCount++;
          }

          if (tempTitle === 'P+LC' || tempTitle === 'P+EG') {
            lcegCount++;
          }
        });
        let employeeRecord = {
          employeeCode: empJoining.employeeCode,
          employeeName: userData.displayName,
          Branch: branch,
          Department: department,
          Designation: designation,
          Company: company,
          presentCount,
          missPunChCount,
          absentCount,
          leaveCount,
          lcegCount,
          halfDayCount,
          weekOffCount,
          holidayCount,
          attendance: lastEntries,
        };
        employeeAttendanceSummary.push(employeeRecord);
      }
    }

    await generateExcelForAttendaceReport4(
      hrLeaveHeader,
      allUser_HrleaveData,
      employeeAttendanceSummary,
      `${YearMM}-Attendance`,
      'xlsx',
      res
    );
  } catch (err) {
    next(err);
  }
};

