exports.getWeekoffDayWorkReport = async (req, res, next) => {
  try {
    const { userMasterID, fromMonth, toMonth, exportData, weekoffstatus } =
      req.body;

    if (
      !userMasterID ||
      (userMasterID && userMasterID.length == 0) ||
      !fromMonth ||
      !toMonth ||
      !exportData ||
      !weekoffstatus
    )
      return res.status(200).json({
        status: 401,
        message: 'Invalid Parameters',
      });

    const condition = {};

    condition.optionalHoliday = false;

    condition.userMasterID = {
      [Sequelize.Op.in]: userMasterID,
    };

    const startDate =
      String(fromMonth).slice(0, 4) +
      '-' +
      String(fromMonth).slice(4, 6) +
      '-' +
      '01';
    const endDate =
      String(toMonth).slice(0, 4) +
      '-' +
      String(toMonth).slice(4, 6) +
      '-' +
      daysInMonth(String(toMonth).slice(4, 6), String(toMonth).slice(0, 4));

    condition.date = {
      [Sequelize.Op.between]: [startDate, endDate],
    };

    if (weekoffstatus == 'W') {
      condition.tableName = 'weekoff';
    }
    if (weekoffstatus == 'H') {
      condition.tableName = 'holiday';
    }
    if (weekoffstatus == 'WH') {
      condition.tableName = ['weekoff', 'holiday'];
    }

    const weekoffDate = await weekoffHolidayTran.findAll({
      where: condition,
      include: [
        {
          required: true,
          model: UserMaster,
          where: { status: 1 },
          attributes: [],
        },
      ],
      order: [['date', 'ASC']],
    });

    const AllWeekOffDate = [...new Set(weekoffDate.map((e) => e.date))];

    const currentDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const rows = await UserMaster.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: userMasterID,
        },
      },
      include: [
        {
          model: EmployeeJoiningDetails,
          attributes: ['employeeCode'],
        },
        {
          model: EmployeeBranch,
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(currentDate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: { [Sequelize.Op.gte]: new Date(currentDate) },
              },
              {
                endDate: { [Sequelize.Op.eq]: null },
              },
            ],
          },
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName', 'branchAddress'],
            },
          ],
        },
        {
          model: EmployeeDepartment,
          attributes: ['departmentID'],
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(currentDate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: { [Sequelize.Op.gte]: new Date(currentDate) },
              },
              {
                endDate: { [Sequelize.Op.eq]: null },
              },
            ],
          },
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          model: EmployeeDesignation,
          attributes: ['designationID'],
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(currentDate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: { [Sequelize.Op.gte]: new Date(currentDate) },
              },
              {
                endDate: { [Sequelize.Op.eq]: null },
              },
            ],
          },
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          required: false,
          model: attendanceTransaction,
          where: {
            AttendanceDate: {
              [Sequelize.Op.in]: AllWeekOffDate,
            },
          },
          attributes: [
            'OutDateTime',
            'InDatetime',
            'InHrs',
            'OutHrs',
            'AttendanceDate',
          ],
        },
      ],
      attributes: ['displayName', 'userNumber', 'userMasterID'],
      order: [['displayName', 'ASC']],
    });

    function formatDateToDDMMYYYYHHMM(isoDateString) {
      const date = new Date(isoDateString);

      // Extract components
      const day = String(date.getDate()).padStart(2, '0');
      const month = String(date.getMonth() + 1).padStart(2, '0'); // Months are 0-based
      const year = date.getFullYear();
      const hours = String(date.getHours()).padStart(2, '0');
      const minutes = String(date.getMinutes()).padStart(2, '0');

      // Format as DD-MM-YYYY HH:mm
      return `${day}-${month}-${year} ${hours}:${minutes}`;
    }

    const finaldata = rows.map((e) => {
      const findWeekoff = weekoffDate
        .filter((f) => f.userMasterID == e.userMasterID)
        .map((g) => g.date);
      const attendanceData = e.attendanceTransactions;

      let result = {};

      AllWeekOffDate.forEach((weekoffDate) => {
        // If the weekoff date is in the user's weekoff data
        if (findWeekoff.includes(weekoffDate)) {
          // Check if the attendance data exists for this weekoff date
          const attendance = attendanceData.find(
            (item) => item.AttendanceDate == weekoffDate
          );
          let InDatetime = '-';
          let OutDatetime = '-';

          if (attendance) {
            if (attendance.InDatetime) {
              InDatetime = formatDateToDDMMYYYYHHMM(attendance.InDatetime);
            }
            if (attendance.OutDateTime) {
              OutDatetime = formatDateToDDMMYYYYHHMM(attendance.OutDateTime);
            }

            // If attendance is present, format it accordingly
            result[weekoffDate] = {
              intime: InDatetime,
              outtime: OutDatetime,
              hrs: attendance.InHrs,
            };
          } else {
            // If attendance is not found for this weekoff date
            result[weekoffDate] = {
              intime: '-',
              outtime: '-',
              hrs: '-',
            };
          }
        } else {
          // If the weekoff date is in allUserWeekoffDates but not in user's weekoff data
          result[weekoffDate] = {
            intime: 'NA',
            outtime: 'NA',
            hrs: 'NA',
          };
        }
      });

      const employeeCode =
        e.employeeJoiningDetails && e.employeeJoiningDetails.length > 0
          ? e.employeeJoiningDetails[0].employeeCode
          : '';
      const branch =
        e.employeeBranches &&
        e.employeeBranches.length > 0 &&
        e.employeeBranches[0].branchMaster
          ? e.employeeBranches[0].branchMaster.branchName
          : '';
      const department =
        e.employeeDepartments &&
        e.employeeDepartments.length > 0 &&
        e.employeeDepartments[0].department
          ? e.employeeDepartments[0].department.departmentName
          : '';
      const designation =
        e.employeeDesignations &&
        e.employeeDesignations.length > 0 &&
        e.employeeDesignations[0].designation
          ? e.employeeDesignations[0].designation.designationName
          : '';

      return {
        'Employee Code': employeeCode,
        'Employee Name': e.displayName,
        Number: e.userNumber,
        Branch: branch,
        Department: department,
        Designation: designation,
        ...result,
      };
    });

    if (exportData) {
      await generateweekoffWorkDayExcel(
        finaldata,
        AllWeekOffDate,
        'WeekOff Day Work Report',
        'xlsx',
        res
      );
      return;
    }

    return res.status(200).json({
      status: 200,
      data: finaldata,
      message: 'Data Fetch SuccessFully',
    });
  } catch (err) {
    next(err);
  }
};

// Convert UTC log data to IST
const convertUTCtoIST = (utcDateTime) => {
  const date = new Date(utcDateTime);
  const istOffset = 5 * 60 + 30; // Offset in minutes
  const istDate = new Date(date.getTime() + istOffset * 60000);
  return istDate.toISOString().replace('T', ' ').slice(0, 16);
};

// Round to minutes (zero seconds and milliseconds)
const roundToMinutes = (dateTime) => {
  const date = new Date(dateTime);
  date.setSeconds(0, 0); // Zero seconds and milliseconds
  return date;
};

// Calculate minutes difference
const calculateMinutesDifference = (start, end) => {
  const startRounded = roundToMinutes(start);
  const endRounded = roundToMinutes(end);
  const diff = (endRounded - startRounded) / 60000; // Difference in minutes
  return Math.round(diff);
};

// Process logs in IST
const processLogsInIST = (shiftdata, logadata) => {
  // Convert log data to IST
  const logsInIST = logadata.map((log) => ({
    ...log.dataValues,
    logDateTimeIST: convertUTCtoIST(log.logDateTime),
  }));

  const output = {
    slot1_In: null,
    slot1_Out: null,
    'slot1_LateBy(Minutes)': null,
    'slot1_EarlyBy(Minutes)': null,
    slot2_In: null,
    slot2_Out: null,
    'slot2_LateBy(Minutes)': null,
    'slot2_EarlyBy(Minutes)': null,
  };

  // Track used logs
  const usedLogs = new Set();

  let slot1InFound = false;
  let slot2InFound = false;

  const slot1startTime = shiftdata['slot1StartTime'];
  const slot1endTime = shiftdata['slot1EndTime'];
  const slot2startTime = shiftdata['slot2StartTime'];
  const slot2endTime = shiftdata['slot2EndTime'];

  // Check for "in" logs for both slots

  const firstInLog = logsInIST.filter(
    (log) =>
      log.direction === 'in' &&
      new Date(log.logDateTimeIST) <= new Date(slot1endTime) &&
      !usedLogs.has(log.logDateTimeIST)
  );

  const secondInLog = logsInIST.filter(
    (log) =>
      log.direction === 'in' &&
      new Date(log.logDateTimeIST) > new Date(slot1endTime) &&
      !usedLogs.has(log.logDateTimeIST)
  );

  if (firstInLog.length > 0) {
    slot1InFound = true;
    output[`slot1_In`] = firstInLog[0].logDateTimeIST;
    usedLogs.add(firstInLog[0].logDateTimeIST);

    let checkOutLog = [];

    // if slot2 log is present in attendancelog

    if (secondInLog.length > 0) {
      // Check for "out" log if available for slot1
      checkOutLog = logsInIST.filter(
        (log) =>
          log.direction === 'out' &&
          !usedLogs.has(log.logDateTimeIST) &&
          new Date(log.logDateTimeIST) >= new Date(slot1startTime) &&
          new Date(log.logDateTimeIST) <=
            new Date(secondInLog[0].logDateTimeIST)
      );
    } else {
      // Check for "out" log if available for slot1
      checkOutLog = logsInIST.filter(
        (log) => log.direction === 'out' && !usedLogs.has(log.logDateTimeIST)
      );
    }

    if (checkOutLog.length > 0) {
      output['slot1_Out'] = checkOutLog[checkOutLog.length - 1].logDateTimeIST;
      usedLogs.add(checkOutLog[checkOutLog.length - 1].logDateTimeIST);
    } else {
      output['slot1_Out'] = null; // If no out log found, set to null
    }
  }

  if (secondInLog.length > 0) {
    slot2InFound = true;
    output['slot2_In'] = secondInLog[0].logDateTimeIST;
    usedLogs.add(secondInLog[0].logDateTimeIST);

    // Check for "out" log if available for slot2
    const checkOutLog = logsInIST.filter(
      (log) =>
        log.direction === 'out' &&
        !usedLogs.has(log.logDateTimeIST) &&
        new Date(log.logDateTimeIST) >= new Date(slot2startTime)
    );

    if (checkOutLog.length > 0) {
      output['slot2_Out'] = checkOutLog[checkOutLog.length - 1].logDateTimeIST;
      usedLogs.add(checkOutLog[checkOutLog.length - 1].logDateTimeIST);
    } else {
      output['slot2_Out'] = null; // If no out log found, set to null
    }
  }

  // Calculate late/early times for slot1
  output['slot1_LateBy(Minutes)'] = slot1InFound
    ? Math.max(
        0,
        calculateMinutesDifference(shiftdata.slot1StartTime, output.slot1_In)
      )
    : null;

  output['slot1_EarlyBy(Minutes)'] = output.slot1_Out
    ? Math.max(
        0,
        calculateMinutesDifference(output.slot1_Out, shiftdata.slot1EndTime)
      )
    : null;

  // Calculate late/early times for slot2
  output['slot2_LateBy(Minutes)'] = slot2InFound
    ? Math.max(
        0,
        calculateMinutesDifference(shiftdata.slot2StartTime, output.slot2_In)
      )
    : null;

  output['slot2_EarlyBy(Minutes)'] = output.slot2_Out
    ? Math.max(
        0,
        calculateMinutesDifference(output.slot2_Out, shiftdata.slot2EndTime)
      )
    : null;

  return output;
};

const getNextDate = (startTime, endTime, date) => {
  let latestDate = date;
  if (new Date(`${date} ${startTime}`) > new Date(`${date} ${endTime}`)) {
    latestDate = new Date(date);
    latestDate.setDate(latestDate.getDate() + 1);

    latestDate = latestDate.toISOString().split('T')[0];
  }

  return latestDate;
};

exports.slotwiseAttendanceReport = async (req, res, next) => {
  try {
    const { userMasterID, startDate, endDate, Export } = req.body;

    const userData = await UserMaster.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: userMasterID,
        },
      },
      include: [
        {
          model: EmployeeDesignation,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date() },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date() } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          model: EmployeeDepartment,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date() },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date() } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          model: EmployeeBranch,
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: new Date() },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date() } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        },
        {
          required: false,
          model: attendanceTransaction,
          where: {
            AttendanceDate: {
              [Sequelize.Op.between]: [new Date(startDate), new Date(endDate)],
            },
          },
          attributes: ['AttendanceTransID', 'AttendanceDate', 'Shift'],
          include: [
            {
              required: false,
              model: AttendanceLogs,
              attributes: ['logDateTime', 'direction'],
              order: [['logDateTime', 'ASC']],
            },
          ],
        },
        {
          model: EmployeeJoiningDetails,
          attributes: ['employeeCode'],
        },
      ],
      order: [['displayName', 'ASC']],
    });

    const allShift = await Shift.findAll({
      where: {
        companyMasterID: userData[0].companyMasterId,
      },
      attributes: ['shiftID'],
      include: [
        {
          model: ShiftTIme,
          attributes: [
            'day',
            'statTime',
            'firsthalfendtime',
            'secondhalfstarttime',
            'endtime',
          ],
        },
      ],
    });

    const finalData = [];

    const datesArray = await getDatesFromDateRange(
      new Date(startDate),
      new Date(endDate)
    );

    for (const user of userData) {
      const tempObj = {};
      const attendnaceData = user.attendanceTransactions || [];

      tempObj['Employee Code'] = user.employeeJoiningDetails?.[0]?.employeeCode;
      tempObj['Employee Name'] = user.displayName;
      tempObj['Employee Number'] = user.userNumber;
      tempObj['Branch'] = user.employeeBranches?.[0]?.branchMaster?.branchName;
      tempObj['Department'] =
        user.employeeDepartments?.[0]?.department?.departmentName;
      tempObj['Designation'] =
        user.employeeDesignations?.[0]?.designation?.designationName;
      tempObj['Date'] = '';

      for (const date of datesArray) {
        const currentDate = date.toISOString().slice(0, 10);
        const attendance = attendnaceData.find(
          (e) =>
            new Date(e.AttendanceDate).getTime() ==
            new Date(currentDate).getTime()
        );

        const tempData = {
          slot1_In: null,
          slot1_Out: null,
          'slot1_LateBy(Minutes)': null,
          'slot1_EarlyBy(Minutes)': null,
          slot2_In: null,
          slot2_Out: null,
          'slot2_LateBy(Minutes)': null,
          'slot2_EarlyBy(Minutes)': null,
        };

        if (!attendance) {
          tempObj[`${currentDate}`] = tempData;
          continue;
        }

        const logData = attendance.attendancelogs.sort(
          (a, b) => new Date(a.logDateTime) - new Date(b.logDateTime)
        );

        // logData.sort((a, b) => new Date(a.logDateTime) - new Date(b.logDateTime));

        const shift = allShift.find((e) => e.shiftID == attendance.Shift);

        if (!shift) {
          tempObj[`${currentDate}`] = tempData;
          continue;
        }

        const day = new Date(currentDate).toLocaleString('en-us', {
          weekday: 'long',
        });

        const shiftTime = shift.shiftTimes.find((e) => e.day == day);

        const shiftdata = {};

        let latestDate = currentDate;

        shiftdata['slot1StartTime'] = `${latestDate} ${shiftTime.statTime}`;

        latestDate = getNextDate(
          shiftTime.statTime,
          shiftTime.firsthalfendtime,
          latestDate
        );

        shiftdata['slot1EndTime'] =
          `${latestDate} ${shiftTime.firsthalfendtime}`;

        latestDate = getNextDate(
          shiftTime.firsthalfendtime,
          shiftTime.secondhalfstarttime,
          latestDate
        );

        shiftdata['slot2StartTime'] =
          `${latestDate} ${shiftTime.secondhalfstarttime}`;

        latestDate = getNextDate(
          shiftTime.secondhalfstarttime,
          shiftTime.endtime,
          latestDate
        );

        shiftdata['slot2EndTime'] = `${latestDate} ${shiftTime.endtime}`;

        tempObj[`${currentDate}`] = processLogsInIST(shiftdata, logData);
      }
      finalData.push(tempObj);
    }

    if (Export)
      return await generateExcel_SlotWise_Attendance_Report(
        finalData,
        'SlotWise_AttendanceReport',
        'xlsx',
        res
      );

    return res.status(200).json({
      status: 200,
      data: finalData,
    });
  } catch (error) {
    next(error);
  }
};

