exports.PT_register = async (req, res, next) => {
  try {
    const { companyMasterID, stateId, YYYYMM, exportType } = req.body;

    const month = String(YYYYMM).slice(4, 6);

    const currentDate =
      String(YYYYMM).slice(0, 4) +
      '-' +
      String(YYYYMM).slice(4, 6) +
      '-' +
      daysInMonth(String(YYYYMM).slice(4, 6), String(YYYYMM).slice(0, 4));

    const monthName =
      month_dict[String(YYYYMM).slice(4, 6)] + '-' + String(YYYYMM).slice(0, 4);

    const includeArray = [
      {
        required: false,
        model: HrSalaryTransaction,
        where: {
          salaryYYYYMM: YYYYMM,
        },
        include: [
          {
            model: HrSalaryMaster,
            as: 'HSM',
            attributes: ['gradeSalaryStructureID', 'EmployeeSalaryAmount'],
            include: [
              {
                model: GradeSalaryStructure,
                as: 'GSS',
                attributes: ['salaryFieldID'],
                include: [
                  {
                    // required: false,
                    model: HRSalaryFields,
                    as: 'HSF',
                    where: {
                      payheadMasterId: [15, 50],
                    },
                    attributes: ['payheadMasterId'],
                  },
                ],
              },
            ],
          },
        ],
      },
      {
        model: HrSalaryMaster,
        where: {
          stateid: stateId,
          [Sequelize.Op.and]:
            Sequelize.literal(`"hrSalaryMasters"."salaryFromYYYYMM" = (
            SELECT MAX("salaryFromYYYYMM") 
            FROM "hrSalaryMasters" 
            WHERE "hrSalaryMasters"."userMasterID" = "userMaster"."userMasterID"
              AND "hrSalaryMasters"."salaryFromYYYYMM" <= ${YYYYMM}
          )`),
        },
        attributes: [],
      },
      {
        model: EmployeeJoiningDetails,
        attributes: ['employeeCode'],
      },
    ];

    if (exportType == 'excel') {
      includeArray.push(
        {
          model: EmployeeDesignation,
          as: 'emp_desig',
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: currentDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: currentDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          model: EmployeeDepartment,
          as: 'emp_dept',
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: currentDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: currentDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          model: EmployeeBranch,
          as: 'emp_branch',
          where: {
            status: 1,
            applicableDate: { [Sequelize.Op.lte]: currentDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: currentDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        }
      );
    }

    const allUserData = await UserMaster.findAll({
      where: {
        companyMasterId: companyMasterID,
        status: 1,
      },
      include: includeArray,
      attributes: ['userMasterID', 'displayName', 'userNumber', 'gender'],
      order: [['displayName', 'ASC']],
    });

    const maxApplicable = await ProfessionalTaxSlabMaster.max(
      'applicableFromYYYYMM',
      {
        where: {
          stateMasterID: stateId,
          month: month,
          applicableFromYYYYMM: { [Sequelize.Op.lte]: String(YYYYMM) },
        },
      }
    );

    const AllSlabs = await ProfessionalTaxSlabMaster.findAll({
      where: {
        stateMasterID: stateId,
        month: month,
        status: 1,
        applicableFromYYYYMM: maxApplicable,
      },
      order: [['fromAmount', 'ASC']],
    });

    const finalData = [];

    let SrNo = 0,
      totalPTAmount = 0,
      totalSalary = 0;

    const slabObject = {};

    for (const data of allUserData) {
      const joining = data.employeeJoiningDetails?.[0] || null;

      const gender = data.gender == 'female' ? 'F' : 'M';

      const obj = {
        SrNo: 0,
        EmployeeCode: joining?.employeeCode || '',
        EmployeeName: data.displayName,
      };

      if (exportType == 'excel') {
        obj['Number'] = data.userNumber;
        obj['Gender'] = data.gender;
        obj['Branch'] = data.emp_branch?.[0]?.branchMaster?.branchName || '';
        obj['Department'] =
          data.emp_dept?.[0]?.department?.departmentName || '';
        obj['Designation'] =
          data.emp_desig?.[0]?.designation?.designationName || '';
      }

      const salaryData = data.hrSalaryTrasactions || [];

      const grossAmount =
        salaryData.find((e) => e.HSM?.GSS?.HSF?.payheadMasterId == 50)
          ?.EmployeeSalaryAmount || 0;

      obj['Salary'] = grossAmount;

      const ptAmount =
        salaryData.find((e) => e.HSM?.GSS?.HSF?.payheadMasterId == 15)
          ?.EmployeeSalaryAmount || 0;

      obj['PT'] = ptAmount;

      if (+ptAmount > 0) {
        SrNo++;
        obj.SrNo = SrNo;
      }

      totalSalary += +grossAmount;
      totalPTAmount += +ptAmount;

      finalData.push(obj);

      const range = AllSlabs.find(
        (e) => +e.fromAmount <= +grossAmount && +e.toAmount >= +grossAmount
      );

      if (!range) continue;

      const key = `${range.fromAmount}_${gender}`;

      if (slabObject[key]) {
        slabObject[key].totalEmployee += 1;
        slabObject[key].totalSalary += +grossAmount;
        slabObject[key].total_PT += +ptAmount;
      } else {
        slabObject[key] = {
          totalEmployee: 1,
          totalSalary: +grossAmount,
          total_PT: +ptAmount,
        };
      }
    }

    const state = await StateMaster.findOne({
      where: {
        stateMasterID: stateId,
      },
      attributes: ['stateName'],
    });

    const summaryData = [];

    if (exportType == 'pdf') {
      AllSlabs.forEach((item) => {
        const femaleData = slabObject[`${item.fromAmount}_F`] || null;
        const maleData = slabObject[`${item.fromAmount}_M`] || null;

        summaryData.push(
          {
            fromAmount: item.fromAmount,
            toAmount: item.toAmount,
            pt: item.femaleTax,
            gender: 'F',
            totalEmployee: femaleData?.totalEmployee || 0,
            totalSalary: femaleData?.totalSalary || 0,
            total_PT: femaleData?.total_PT || 0,
          },
          {
            fromAmount: item.fromAmount,
            toAmount: item.toAmount,
            pt: item.maleTax,
            gender: 'M',
            totalEmployee: maleData?.totalEmployee || 0,
            totalSalary: maleData?.totalSalary || 0,
            total_PT: maleData?.total_PT || 0,
          }
        );
      });

      const companyMaster = await companyMasters.findOne({
        where: {
          companyMasterID,
        },
        attributes: ['companyName', 'companyAddress'],
      });

      const pdfData = {
        data: finalData,
        summaryData,
        totalData: {
          Exclude_PT_ZERO: SrNo,
          PT: summaryData.reduce((acc, obj) => acc + +obj.pt, 0),
          Total_emp: summaryData.reduce(
            (acc, obj) => acc + +obj.totalEmployee,
            0
          ),
          Total_salary: summaryData.reduce(
            (acc, obj) => acc + +obj.totalSalary,
            0
          ),
          Total_PT: summaryData.reduce((acc, obj) => acc + +obj.total_PT, 0),
        },
        companyName: companyMaster?.companyName || '',
        companyAdd: companyMaster?.companyAddress || '',
        stateName: state?.stateName || '',
        month: monthName,
      };

      const filePath = await getTemplateHTML('PTRegister');

      const file = await readFile(filePath);
      const template = Handlebars.compile(file);
      const html = template(pdfData);

      const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox'],
      });
      const page = await browser.newPage();

      // Set the HTML content of the page
      await page.setContent(html);

      // Generate PDF
      const pdfBuffer = await page.pdf({
        format: 'A4', // Page format (A4 in this case)
        printBackground: true, // print background
        margin: { top: '20px', bottom: '20px' },
      });
      await browser.close();

      let base64path = Buffer.from(pdfBuffer).toString('base64');

      return res.status(200).json({
        status: 200,
        data: base64path,
      });
    }

    if (exportType == 'excel') {
      finalData.push({
        SrNo: '',
        EmployeeCode: '',
        Designation: 'Total',
        Salary: +totalSalary,
        PT: +totalPTAmount,
      });

      return await generateExcel(
        finalData,
        `PT Register ${state?.stateName} ${monthName}`,
        'xlsx',
        res
      );
    }
  } catch (error) {
    next(error);
  }
};

exports.attendance_dashboard = async (req, res, next) => {
  try {
    const {
      page,
      limit,
      companyId,
      branchId,
      date,
      type,
      Export,
      departmentID,
      designationID,
      divisionId,
      workingAreaId,
    } = req.body;

    if (!companyId || !date) {
      return res.status(200).json({
        status: 401,
        message: message.usermessage.ValidParameters,
      });
    }

    const paginatecondition =
      !Export && page && limit ? { offset: (page - 1) * limit, limit } : {};

    let attendanceCondition = {
      AttendanceDate: date,
    };

    let attendanceInclude = {
      model: attendanceTransaction,
      required: false, // default
      where: attendanceCondition,
      attributes: [
        'InDatetime',
        'OutDateTime',
        'AttendanceDate',
        'AttendanceTransID',
      ],
    };

    if (type === 'in') {
      attendanceInclude.required = true;
    }

    if (type === 'out') {
      attendanceCondition.OutDateTime = {
        [Sequelize.Op.ne]: null,
      };
      attendanceInclude.required = true;
    }

    const whereConditions = {
      status: 1,
      companyMasterId: companyId,
    };

    if (type === 'notIn') {
      whereConditions[Sequelize.Op.and] = [
        Sequelize.literal(`
          NOT EXISTS (
            SELECT 1 
            FROM "attendanceTransactions" AS "at" 
            WHERE "at"."userMasterID" = "userMaster"."userMasterID" 
            AND "at"."AttendanceDate" = '${date}'
          )
        `),
      ];
    }

    const { rows: data, count } = await UserMaster.findAndCountAll({
      where: whereConditions,
      ...paginatecondition,
      attributes: userAttributes,
      order: [['displayName', 'ASC']],
      include: [
        {
          required: designationID && designationID.length ? true : false,
          model: EmployeeDesignation,
          as: 'emp_desig',
          where: {
            status: 1,
            ...(designationID &&
              (!Array.isArray(designationID) || designationID.length) && {
                designationID,
              }),
            applicableDate: { [Sequelize.Op.lte]: date },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: date } },
              { endDate: null },
            ],
          },
          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          required: departmentID && departmentID.length ? true : false,
          model: EmployeeDepartment,
          as: 'emp_dept',
          where: {
            status: 1,
            ...(departmentID &&
              (!Array.isArray(departmentID) || departmentID.length) && {
                departmentID,
              }),
            applicableDate: { [Sequelize.Op.lte]: date },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: date } },
              { endDate: null },
            ],
          },

          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          required: branchId && branchId.length ? true : false,
          model: EmployeeBranch,
          as: 'emp_branch',
          where: {
            status: 1,
            ...(branchId &&
              (!Array.isArray(branchId) || branchId.length) && {
                branchID: branchId,
              }),
            applicableDate: { [Sequelize.Op.lte]: date },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: date } },
              { endDate: null },
            ],
          },

          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        },
        {
          model: EmployeeDivision,
          where: {
            status: 1,
            ...(divisionId &&
              (!Array.isArray(divisionId) || divisionId.length) && {
                divisionId,
              }),
            startDate: { [Sequelize.Op.lte]: new Date(date) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(date) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: divisionId && divisionId.length ? true : false,
          attributes: ['divisionId'],
          include: [
            {
              model: Division,
              attributes: ['divisionName'],
            },
          ],
        },
        {
          model: EmployeeWorkingArea,
          where: {
            status: 1,
            ...(workingAreaId &&
              (!Array.isArray(workingAreaId) || workingAreaId.length) && {
                workingAreaId,
              }),
            startDate: { [Sequelize.Op.lte]: new Date(date) },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: new Date(date) } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: workingAreaId.length ? true : false,
          attributes: ['workingAreaId'],
          include: [
            {
              model: WorkingArea,
              attributes: ['workingAreaName'],
            },
          ],
        },
        {
          model: EmployeeJoiningDetails,
          attributes: ['employeeCode'],
        },
        ...(type !== 'notIn' ? [attendanceInclude] : []),
      ],
    });

    if (Export) {
      const finaldata = data.map((e) => {
        const attendance = e.attendanceTransactions?.[0] || null;

        return {
          'Employee Code': e.employeeJoiningDetails?.[0]?.employeeCode || '',
          'Employee Name': e.displayName,
          Number: e.userNumber,
          Branch: e.emp_branch?.[0]?.branchMaster?.branchName || '',
          Department: e.emp_dept?.[0]?.department?.departmentName || '',
          Designation: e.emp_desig?.[0]?.designation?.designationName || '',
          AttendanceDate: attendance?.AttendanceDate || '',
          'PunchIn Time': attendance
            ? asiaKolkataDateTime(attendance.InDatetime)
            : '',
          'PunchOut Time':
            attendance && attendance.OutDateTime
              ? asiaKolkataDateTime(attendance.OutDateTime)
              : '',
        };
      });

      return await generateExcel(finaldata, 'Attendance Data', 'xlsx', res);
    }

    return res.status(200).json({
      status: 200,
      data,
      totalcount: count,
    });
  } catch (error) {
    next(error);
  }
};

exports.attendanceCorrectionReport = async (req, res, next) => {
  try {
    const { userMasterID, fromDate, toDate, page, limit, exportData } =
      req.body;

    const paginationQuery = {};
    const condition = {};
    if (page && limit) {
      paginationQuery.offset = (page - 1) * limit;
      paginationQuery.limit = limit;
    }
    const order = [['createdAt', 'DESC']];

    condition.userMasterID = userMasterID;
    if (fromDate && toDate)
      condition.AttendanceDate = {
        [Sequelize.Op.between]: [new Date(fromDate), new Date(toDate)],
      };

    const currentdate = asiaKolkataDateTime(new Date()).slice(0, 10);
    const attendanceCorrectionData =
      await AttendanceCorrectionRequest.findAndCountAll({
        distinct: true,
        where: condition,
        ...paginationQuery,
        order: order,
        include: [
          {
            model: UserMaster,
            attributes: ['displayName', 'userMasterID'],
            include: [
              {
                model: EmployeeBranch,
                where: {
                  status: 1,
                  applicableDate: {
                    [Sequelize.Op.lte]: new Date(currentdate),
                  },
                  [Sequelize.Op.or]: [
                    {
                      endDate: {
                        [Sequelize.Op.gte]: new Date(currentdate),
                      },
                    },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },
                required: false,
                attributes: ['branchID'],
                include: [
                  {
                    model: BranchMaster,
                    as: 'branchMaster',
                    attributes: ['branchName'],
                  },
                ],
              },
              {
                required: false,
                model: EmployeeDesignation,
                where: {
                  status: 1,
                  applicableDate: { [Sequelize.Op.lte]: new Date(currentdate) },
                  [Sequelize.Op.or]: [
                    { endDate: { [Sequelize.Op.gte]: new Date(currentdate) } },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },

                attributes: ['designationID'],
                include: [
                  {
                    model: Designation,
                    as: 'designation',
                    attributes: ['designationName'],
                  },
                ],
              },
              {
                required: false,
                model: EmployeeDepartment,
                where: {
                  status: 1,
                  applicableDate: { [Sequelize.Op.lte]: new Date(currentdate) },
                  [Sequelize.Op.or]: [
                    { endDate: { [Sequelize.Op.gte]: new Date(currentdate) } },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },

                attributes: ['departmentID'],
                include: [
                  {
                    model: Department,
                    as: 'department',
                    attributes: ['departmentName'],
                  },
                ],
              },
              {
                required: false,
                model: EmployeeDivision,
                where: {
                  status: 1,
                  startDate: { [Sequelize.Op.lte]: new Date(currentdate) },
                  [Sequelize.Op.or]: [
                    { endDate: { [Sequelize.Op.gte]: new Date(currentdate) } },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },
                required: false,
                attributes: ['divisionId', 'startDate'],
                include: [
                  {
                    model: Division,
                    attributes: ['divisionName'],
                  },
                ],
              },
              {
                model: EmployeeJoiningDetails,
                attributes: ['employeeCode'],
              },
              {
                required: false,
                separate: true,
                model: AuthorizationDetails,
                where: {
                  AuthorizationMasterID:
                    authorizationMasterTypes.attendanceCorrection,
                  status: 1,
                },
                include: [
                  {
                    model: AuthorizationCriteriaMaster,
                    attributes: ['AuthorizationCriteria'],
                  },
                ],
              },
            ],
            as: 'employee',
          },
          {
            model: AttendanceCorrectionLogs,
          },
          {
            model: AttendanceCorrectionAuthorization,
            include: [
              {
                model: UserMaster,
                attributes: ['displayName'],
                as: 'authorizedPerson',
              },
            ],
          },
          {
            model: UserMaster,
            attributes: ['displayName'],
            as: 'createdByUser',
          },
          {
            model: UserMaster,
            attributes: ['displayName'],
            as: 'updatedByUser',
          },
        ],
      });

    const formattedData = attendanceCorrectionData.rows.map((x) => {
      const data = {};

      data.displayName = x.employee.displayName;
      data.employeeCode = x.employee.employeeJoiningDetails[0]?.employeeCode;
      data.Branch = x.employee.employeeBranches[0]?.branchMaster.branchName;
      data.Department =
        x.employee.employeeDepartments[0]?.department.departmentName;
      data.Designation =
        x.employee.employeeDesignations[0]?.designation.designationName;
      data.Division = x.employee.employeeDivisions[0]?.division.divisionName;
      data.AttendanceDate = moment(x.AttendanceDate, 'YYYY-MM-DD').format(
        'DD-MM-YYYY'
      );
      data.createdAt = moment(x.createdAt, 'YYYY-MM-DDTHH:mm:ss').format(
        'DD-MM-YYYY HH:mm'
      );
      data.updatedAt = moment(x.updatedAt, 'YYYY-MM-DDTHH:mm:ss').format(
        'DD-MM-YYYY HH:mm'
      );
      data.authorizationStatus =
        x.authorizationStatus == 0 ||
        x.authorizationStatus == 1 ||
        x.authorizationStatus == 2
          ? 'Pending'
          : x.authorizationStatus == 3
            ? 'Approved'
            : 'Rejected';
      data.remark = x.remark;
      data.authCriteria =
        x.employee.authorizationDetails[0]?.AuthorizationCriteriaMaster.AuthorizationCriteria;
      data.attendanceStatus = x.attendanceCorrectionLogs[0]?.attendanceStatus
        ? x.attendanceCorrectionLogs[0]?.attendanceStatus
        : '';
      if (x.attendanceCorrectionLogs?.length > 1) {
        const sortedData = x?.attendanceCorrectionLogs?.sort(
          (a, b) => a?.logDateTime - b?.logDateTime
        );
        data.logTime = sortedData.map(
          (x) =>
            x.direction +
            ': ' +
            moment(x.logDateTime, 'YYYY-MM-DDTHH:mm:ss').format(
              'DD-MM-YYYY HH:mm'
            )
        );
      }
      data.createBy = x.createdByUser?.displayName;
      data.updateBy = x.updatedByUser?.displayName;
      data.authorizations = x.attendanceCorrectionAuthorizations.map(
        (a) =>
          a.authorizedPerson?.displayName +
          '-' +
          (a.authStatus == 0
            ? 'Rejected'
            : a.authStatus == 2
              ? 'Pending'
              : 'Approved')
      );
      return data;
    });

    if (exportData) {
      return await generateExcelForAttendanceCorrectionReport(
        formattedData,
        'Attendance Correction Request Report',
        'xlsx',
        res
      );
    }

    return res.status(200).json({
      status: 200,
      data: formattedData,
      totalcount: attendanceCorrectionData.count,
    });
  } catch (error) {
    next(error);
  }
};

exports.expenseClaimReport = async (req, res, next) => {
  try {
    let {
      companyMasterID,
      userMasterID,
      fromDate,
      toDate,
      expenseType,
      status,
      page = 1,
      limit = 10,
      exportData,
      exportFileType,
    } = req.body;

    if (!companyMasterID || !fromDate || !toDate || !expenseType)
      return res
        .status(statusCodes.BAD_REQUEST)
        .json({ message: message.errorMessage.INVALID_FILTER_FIELDS });

    const paginationQuery = {};
    if (!exportData) {
      paginationQuery.offset = (+page - 1) * +limit;
      paginationQuery.limit = +limit;
    }

    const expenseTypeCondition = {};
    if (expenseType === expenseTypes.VISIT) {
      expenseTypeCondition.visitID = { [Sequelize.Op.ne]: null };
    }
    if (expenseType === expenseTypes.TOUR) {
      expenseTypeCondition.ToursMasterID = { [Sequelize.Op.ne]: null };
    }
    if (expenseType === expenseTypes.PERSONAL) {
      expenseTypeCondition.visitID = null;
      expenseTypeCondition.ToursMasterID = null;
      expenseTypeCondition.projectID = null;
    }
    if (expenseType === expenseTypes.PROJECT) {
      expenseTypeCondition.projectID = { [Sequelize.Op.ne]: null };
    }

    const condition = { status: { [Sequelize.Op.ne]: 10 } };

    const statusConditions = [];
    const hasPaid = status.includes(expenseApprovalTypes.PAID);
    const hasApproved = status.includes(expenseApprovalTypes.APPROVED);
    const hasPending = status.includes(expenseApprovalTypes.PENDING);
    const hasRejected = status.includes(expenseApprovalTypes.REJECTED);

    // Special case: Both PAID and APPROVED
    if (hasPaid && hasApproved) {
      statusConditions.push({
        authorizationStatus: '3',
      });
    } else {
      if (hasPaid) {
        statusConditions.push({
          authorizationStatus: '3',
          [Sequelize.Op.or]: [
            { erpJvid: { [Sequelize.Op.ne]: null } },
            { payment_Id: { [Sequelize.Op.ne]: null } },
          ],
        });
      }

      if (hasApproved) {
        statusConditions.push({
          authorizationStatus: '3',
          erpJvid: { [Sequelize.Op.eq]: null },
          payment_Id: { [Sequelize.Op.eq]: null },
        });
      }
    }

    if (hasPending) {
      statusConditions.push({
        authorizationStatus: { [Sequelize.Op.in]: ['0', '1', '2'] },
      });
    }

    if (hasRejected) {
      statusConditions.push({
        authorizationStatus: '4',
      });
    }

    if (statusConditions.length > 0) {
      condition[Sequelize.Op.or] = statusConditions;
    }

    condition.version = { [Sequelize.Op.is]: null };
    if (fromDate && toDate) {
      expenseTypeCondition.expense_date = {
        [Sequelize.Op.between]: [new Date(fromDate), new Date(toDate)],
      };
    }
    if (userMasterID && userMasterID.length) {
      expenseTypeCondition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };
    }

    const currentDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const expenseTransIncludeModel = [
      {
        model: ExpenseHead,
        attributes: [
          'expenseHeadId',
          'expenseHead',
          'accountHeadID',
          'expenseCategoryId',
        ],
        include: [
          {
            model: ExpenseCategory,
            attributes: ['expenseCategoryId', 'expenseCategory'],
          },
        ],
      },
      {
        required: true,
        model: UserExpense,
        as: 'userExpense',
        attributes: [
          'expense_date',
          'visitID',
          'ToursMasterID',
          'userMasterID',
          'projectID',
        ],
        where: expenseTypeCondition,
        include: [
          {
            required: true,
            model: UserMaster,
            where: { companyMasterId: companyMasterID },
            ...accessibleUsers(req.userDetails),

            attributes: userAttributes,
            include: [
              {
                required: false,
                model: EmployeeJoiningDetails,
                attributes: ['employeeCode'],
              },
              {
                required: false,
                separate: true,
                model: EmployeeBranch,
                where: {
                  status: 1,
                  applicableDate: { [Sequelize.Op.lte]: new Date(currentDate) },
                  [Sequelize.Op.or]: [
                    { endDate: { [Sequelize.Op.gte]: new Date(currentDate) } },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },
                attributes: ['branchID'],
                include: [
                  {
                    model: BranchMaster,
                    as: 'branchMaster',
                    attributes: ['branchName'],
                  },
                ],
              },
              {
                required: false,
                separate: true,
                model: EmployeeDepartment,
                where: {
                  status: 1,
                  applicableDate: { [Sequelize.Op.lte]: new Date(currentDate) },
                  [Sequelize.Op.or]: [
                    { endDate: { [Sequelize.Op.gte]: new Date(currentDate) } },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },
                attributes: ['departmentID'],
                include: [
                  {
                    model: Department,
                    as: 'department',
                    attributes: ['departmentName'],
                  },
                ],
              },
              {
                required: false,
                separate: true,
                model: EmployeeDesignation,
                where: {
                  status: 1,
                  applicableDate: { [Sequelize.Op.lte]: new Date(currentDate) },
                  [Sequelize.Op.or]: [
                    { endDate: { [Sequelize.Op.gte]: new Date(currentDate) } },
                    { endDate: { [Sequelize.Op.eq]: null } },
                  ],
                },
                attributes: ['designationID'],
                include: [
                  {
                    model: Designation,
                    as: 'designation',
                    attributes: ['designationName'],
                  },
                ],
              },
            ],
          },
        ],
      },
    ];

    if (exportData) {
      const batchSize = 5000; // Reduce to control memory usage
      let offset = 0;
      let hasMore = true;
      let rowCount = 0;

      const exportDir = path.join(__dirname, '../uploads/expense-Claim-report');
      if (!fs.existsSync(exportDir)) {
        fs.mkdirSync(exportDir, { recursive: true });
      }

      const fileName = `${companyMasterID}_Expense_Claim_Report_${Date.now()}.xlsx`;
      const filePath = path.join(exportDir, fileName);

      const workbook = new Excel.stream.xlsx.WorkbookWriter({
        filename: filePath,
      });
      const worksheet = workbook.addWorksheet('Expense Claim Report');

      const headerRow = worksheet.addRow([
        'Employee Code',
        'Employee Name',
        'Employee Number',
        'Branch',
        'Department',
        'Designation',
        'Expense Date',
        'Expense Category',
        'Expense Head',
        'Amount',
        'Description',
        'Expense Status',
      ]);

      formatFirstRow(worksheet, 1);

      headerRow.commit(); // ✅ Now it's safe

      while (hasMore) {
        const batchRows = await UserExpenseTransaction.findAll({
          where: condition,
          attributes: [
            'userExpenseTransactionID',
            'userExpenseID',
            'expenseHeadId',
            'expenseAmount',
            'version',
            'erpJvid',
            'authorizationStatus',
            'status',
            'createdAt',
            'description',
          ],
          offset,
          limit: batchSize,
          include: expenseTransIncludeModel,
          order: [[Sequelize.literal(`"userExpense.expense_date"`), 'DESC']],
        });

        hasMore = batchRows.length === batchSize;
        offset += batchSize;

        if (batchRows.length === 0 && rowCount === 0) {
          console.error('❌ No data found to generate the file!');
          throw new Error('No data found to generate the file!');
        }

        for (let idx = 0; idx < batchRows.length; idx++) {
          const e = batchRows[idx];
          let authorizationStatusData = 'Pending';
          if (+e.authorizationStatus == 3) {
            authorizationStatusData = 'Approved';
            if (e.erpJvid || e.payment_Id) {
              authorizationStatusData = 'Paid';
            }
          } else if (+e.authorizationStatus == 4) {
            authorizationStatusData = 'Rejected';
          }
          try {
            const row = [
              e.userExpense?.userMaster?.employeeJoiningDetails?.[0]
                ?.employeeCode || '',
              e.userExpense?.userMaster?.displayName || '',
              e.userExpense?.userMaster?.userNumber || '',
              e.userExpense?.userMaster?.employeeBranches?.[0]?.branchMaster
                ?.branchName || '',
              e.userExpense?.userMaster?.employeeDepartments?.[0]?.department
                ?.departmentName || '',
              e.userExpense?.userMaster?.employeeDesignations?.[0]?.designation
                ?.designationName || '',
              moment(e.userExpense?.expense_date, 'YYYY-MM-DD').format(
                'DD-MM-YYYY'
              ) || '',
              e.expenseHead?.expenseCategory?.expenseCategory || '',
              e.expenseHead?.expenseHead || '',
              e.expenseAmount,
              e.description,
              authorizationStatusData || '', // Authorization status
            ];
            worksheet.addRow(row).commit();
            rowCount++;
          } catch (err) {
            console.error(`⚠️ Error writing row ${idx} of batch:`, err);
          }
        }
      }
      await workbook.commit();

      res.download(filePath, fileName, (err) => {
        if (err) {
          console.error('❌ Error sending file to client:', err);
          return res.status(500).send('Error sending file');
        }

        // Optional: Delete file after download
        fs.unlink(filePath, (unlinkErr) => {
          if (unlinkErr) {
            console.error('⚠️ Failed to delete file:', unlinkErr);
          } else {
            console.log('🗑️ File deleted successfully after download.');
          }
        });
      });
    } else {
      // Non-export: paginated result
      const { rows, count } = await UserExpenseTransaction.findAndCountAll({
        where: condition,
        attributes: [
          'userExpenseTransactionID',
          'userExpenseID',
          'expenseHeadId',
          'expenseAmount',
          'description',
          'version',
          'erpJvid',
          'authorizationStatus',
          'status',
          'createdAt',
        ],
        ...paginationQuery,
        include: expenseTransIncludeModel,
        order: [[Sequelize.literal(`"userExpense.expense_date"`), 'DESC']],
      });

      return res.status(200).json({
        data: rows,
        totalcount: count,
      });
    }
  } catch (err) {
    next(err);
  }
};

exports.marsExpenseReport = async (req, res, next) => {
  try {
    let {
      companyMasterID,
      userMasterID,
      fromDate,
      toDate,
      projectID,
      expenseCategoryId,
      status,
      page = 1,
      limit = 10,
      exportData,
    } = req.body;

    if (!companyMasterID || !status)
      return res
        .status(statusCodes.BAD_REQUEST)
        .json({ message: message.errorMessage.INVALID_FILTER_FIELDS });

    const paginationQuery = {};
    if (!exportData && page && limit) {
      paginationQuery.offset = (+page - 1) * +limit;
      paginationQuery.limit = +limit;
    }

    const expenseTypeCondition = {};
    if (fromDate && toDate) {
      expenseTypeCondition.expense_date = {
        [Sequelize.Op.between]: [new Date(fromDate), new Date(toDate)],
      };
    }
    if (userMasterID && userMasterID.length) {
      expenseTypeCondition.userMasterID = {
        [Sequelize.Op.in]: userMasterID,
      };
    }
    if (projectID && projectID.length) {
      expenseTypeCondition.projectID = { [Sequelize.Op.in]: projectID };
    }
    const expenseTransCondition = { status: { [Sequelize.Op.ne]: 10 } };

    if (status === expenseApprovalTypes.APPROVED) {
      expenseTransCondition.authorizationStatus = '3';
    } else if (status === expenseApprovalTypes.PENDING) {
      expenseTransCondition.authorizationStatus = {
        [Sequelize.Op.in]: ['0', '1', '2'],
      };
    }

    const expenseCategoryCondition = {};
    if (expenseCategoryId) {
      expenseCategoryCondition.expenseCategoryId = expenseCategoryId;
    }
    const currentdate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const { rows: userExpenseData, count } = await UserExpense.findAndCountAll({
      where: expenseTypeCondition,
      ...paginationQuery,
      order: [['expense_date', 'DESC']],
      subQuery: false,
      attributes: [
        'userExpenseID',
        'expense_date',
        'status',
        'projectID',
        'createdAt',
        'updatedAt',
      ],
      include: [
        {
          required: true,
          model: UserExpenseTransaction,
          as: 'ut',
          where: expenseTransCondition,
          attributes: [
            'userExpenseTransactionID',
            'userExpenseID',
            'expenseHeadId',
            'expenseAmount',
            'authorizationStatus',
            'status',
            'description',
          ],
          include: [
            {
              required: expenseCategoryId ? true : false,
              model: ExpenseHead,
              as: 'eh',
              attributes: [
                'expenseHeadId',
                'expenseHead',
                'accountHeadID',
                'expenseCategoryId',
              ],
              where: expenseCategoryCondition,
              include: [
                {
                  model: ExpenseCategory,
                  as: 'ec',
                  attributes: ['expenseCategoryId', 'expenseCategory'],
                },
              ],
            },
          ],
        },
        {
          required: true,
          model: UserMaster,
          attributes: userAttributes,
          include: [
            {
              required: false,
              separate: true,
              model: EmployeeDesignation,
              where: {
                status: 1,
                applicableDate: {
                  [Sequelize.Op.lte]: new Date(currentdate),
                },
                [Sequelize.Op.or]: [
                  {
                    endDate: { [Sequelize.Op.gte]: new Date(currentdate) },
                  },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['designationID'],
              include: [
                {
                  model: Designation,
                  as: 'designation',
                  attributes: ['designationName'],
                },
              ],
            },
            {
              required: false,
              separate: true,

              model: EmployeeDepartment,
              where: {
                status: 1,
                applicableDate: {
                  [Sequelize.Op.lte]: new Date(currentdate),
                },
                [Sequelize.Op.or]: [
                  {
                    endDate: { [Sequelize.Op.gte]: new Date(currentdate) },
                  },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },

              attributes: ['departmentID'],
              include: [
                {
                  model: Department,
                  as: 'department',
                  attributes: ['departmentName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeBranch,
              separate: true,

              where: {
                status: 1,
                applicableDate: {
                  [Sequelize.Op.lte]: new Date(currentdate),
                },
                [Sequelize.Op.or]: [
                  {
                    endDate: { [Sequelize.Op.gte]: new Date(currentdate) },
                  },
                  { endDate: { [Sequelize.Op.eq]: null } },
                ],
              },
              required: false,
              attributes: ['branchID'],
              include: [
                {
                  model: BranchMaster,
                  as: 'branchMaster',
                  attributes: ['branchName'],
                },
              ],
            },
            {
              required: false,
              model: EmployeeJoiningDetails,
              attributes: ['employeeCode'],
            },
          ],
        },
        {
          model: Project,
        },
      ],
    });
    for (let item of userExpenseData) {
      item.dataValues.totalExpense = 0;
      for (let trans of item.ut) {
        item.dataValues.totalExpense += trans.expenseAmount;
      }
      const createdAtDate = new Date(item.dataValues.createdAt);
      const aprrovedDate = new Date(item.dataValues.updatedAt);

      const ageingDays =
        Math.floor(
          (new Date().getTime() - createdAtDate.getTime()) /
            (1000 * 60 * 60 * 24)
        ) + 1;

      item.dataValues.ageingDays = ageingDays;
      const tatDays =
        Math.floor(
          (aprrovedDate.getTime() - createdAtDate.getTime()) /
            (1000 * 60 * 60 * 24)
        ) + 1;
      item.dataValues.tatDays = tatDays;
    }

    if (exportData) {
      const finalDataToExport = [];
      let index = 0;
      for (let item of userExpenseData) {
        const transData = item.ut || [];
        for (let tran of transData) {
          const Info = [
            index + 1,
            item.userMaster.displayName,
            item.userMaster.userNumber,
            item.userMaster.employeeJoiningDetails?.[0]?.employeeCode || '',
            item.userMaster.employeeBranches?.[0]?.branchMaster?.branchName ||
              '',
            item.employeeDepartments?.[0]?.department?.departmentName || '',
            item.employeeDesignations?.[0]?.designation?.designationName || '',
            new Date(item.createdAt),
            status === expenseApprovalTypes.APPROVED
              ? item.dataValues.tatDays
              : item.dataValues.ageingDays,
            moment(item.expense_date, 'YYYY-MM-DD').format('DD-MM-YYYY') || '',
            item.userExpenseID,
            item.project?.display_id || '',
            item.project?.projectName || '',
            tran.eh?.ec?.expenseCategory || '', //Main Category
            tran.eh?.expenseHead || '', //Sub Category
            tran.expenseAmount, // Expense Amount
            tran.description, //Description
          ];
          finalDataToExport.push(Info);
        }
        index++;
      }
      await generateExcelForMarsExpenseReport(
        finalDataToExport,
        'Expense Report',
        'xlsx',
        res,
        status
      );
      return;
    }
    return res.status(200).json({
      totalcount: count,
      data: userExpenseData,
    });
  } catch (err) {
    next(err);
  }
};

exports.completedTenureReport = async (req, res, next) => {
  try {
    let {
      companyMasterID,
      page = 1,
      limit = 10,
      exportData,
      month,
      userMasterID,
    } = req.body;

    if (!companyMasterID || !userMasterID || userMasterID.length == 0 || !month)
      return res
        .status(statusCodes.BAD_REQUEST)
        .json({ message: message.errorMessage.INVALID_FILTER_FIELDS });

    const paginationQuery = {};
    if (!exportData && page && limit) {
      paginationQuery.offset = (+page - 1) * +limit;
      paginationQuery.limit = +limit;
    }

    const currentDate = asiaKolkataDateTime(new Date()).slice(0, 10);
    const userCondition = {
      status: 1,
      companyMasterId: companyMasterID,
      userMasterID: {
        [Sequelize.Op.in]: userMasterID,
      },
    };

    const monthsAgoDate = moment(currentDate, 'YYYY-MM-DD').subtract(
      month,
      'months'
    );
    const formattedDate = monthsAgoDate.format('YYYY-MM-DD');
    const { rows: userData, count } = await UserMaster.findAndCountAll({
      where: userCondition,
      ...paginationQuery,
      distinct: true,
      order: [['displayName', 'ASC']],
      attributes: userAttributes,
      include: [
        {
          required: true,
          model: EmployeeJoiningDetails,
          where: {
            joiningDate: {
              [Sequelize.Op.lte]: formattedDate,
            },
            [Sequelize.Op.or]: [
              { leavingDate: { [Sequelize.Op.eq]: null } },
              { leavingDate: { [Sequelize.Op.gte]: currentDate } },
              {
                leavingDate: {
                  [Sequelize.Op.eq]: '',
                },
              },
            ],
          },
          attributes: ['employeeCode', 'joiningDate', 'leavingDate'],
        },
        {
          required: false,
          model: EmployeeDesignation,
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(currentDate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: { [Sequelize.Op.gte]: new Date(currentDate) },
              },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['designationID'],
          include: [
            {
              model: Designation,
              as: 'designation',
              attributes: ['designationName'],
            },
          ],
        },
        {
          required: false,
          model: EmployeeDepartment,
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(currentDate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: { [Sequelize.Op.gte]: new Date(currentDate) },
              },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['departmentID'],
          include: [
            {
              model: Department,
              as: 'department',
              attributes: ['departmentName'],
            },
          ],
        },
        {
          required: false,
          model: EmployeeBranch,
          where: {
            status: 1,
            applicableDate: {
              [Sequelize.Op.lte]: new Date(currentDate),
            },
            [Sequelize.Op.or]: [
              {
                endDate: { [Sequelize.Op.gte]: new Date(currentDate) },
              },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          required: false,
          attributes: ['branchID'],
          include: [
            {
              model: BranchMaster,
              as: 'branchMaster',
              attributes: ['branchName'],
            },
          ],
        },
        {
          required: false,
          model: EmployeeDivision,
          where: {
            status: 1,
            startDate: { [Sequelize.Op.lte]: currentDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: currentDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },

          attributes: ['divisionId', 'startDate'],
          include: [
            {
              model: Division,
              attributes: ['divisionName'],
            },
          ],
        },

        {
          required: false,
          model: EmployeeWorkingArea,
          where: {
            status: 1,
            startDate: { [Sequelize.Op.lte]: currentDate },
            [Sequelize.Op.or]: [
              { endDate: { [Sequelize.Op.gte]: currentDate } },
              { endDate: { [Sequelize.Op.eq]: null } },
            ],
          },
          attributes: ['workingAreaId', 'startDate'],
          include: [
            {
              model: WorkingArea,
              attributes: ['workingAreaName'],
            },
          ],
        },
      ],
    });

    if (exportData) {
      const finaldata = userData.map((e) => {
        const joiningDate = e?.employeeJoiningDetails?.[0]?.joiningDate;
        const leavingDate = e?.employeeJoiningDetails?.[0]?.leavingDate;
        return {
          'Employee Code': e?.employeeJoiningDetails?.[0]?.employeeCode || '',
          'Employee Name': e.displayName,
          'Employee Number': e.userNumber,
          Branch: e.employeeBranches?.[0]?.branchMaster?.branchName || '',
          Department:
            e.employeeDepartments?.[0]?.department?.departmentName || '',
          Designation:
            e.employeeDesignations?.[0]?.designation?.designationName || '',
          Division: e.employeeDivisions?.[0]?.division?.divisionName || '',
          'Working Area':
            e.employeeWorkingAreas?.[0]?.workingArea?.workingAreaName || '',
          'Joining Date': joiningDate
            ? moment(joiningDate).format('DD-MM-YYYY')
            : '',
          'Leaving Date': leavingDate
            ? moment(leavingDate).format('DD-MM-YYYY')
            : '',
        };
      });
      await generateExcel(finaldata, 'Completed Tenure Report', 'xlsx', res);
      return;
    }
    return res.status(200).json({
      totalcount: count,
      data: userData,
    });
  } catch (err) {
    next(err);
  }
};

exports.officeExpenseReport = async(req, res, next) => {
  try {

    const {
      companyMasterID,
      branchMasterID,
      siteID,
      fromDate,
      toDate,
      status,
      page,
      limit,
      exportData
    } = await req.body;

    if(!companyMasterID && branchMasterID && siteID){
      return res.status(statusCodes.BAD_REQUEST).json({ message: message.errorMessage.INVALID_FILTER_FIELDS });
    }

    const paginationQuery = page && limit && !exportData ? {
      limit: limit,
      offset: (page - 1) * limit
    } : {};

    const companyCondition = {};
    if(companyMasterID) companyCondition.companyMasterID = companyMasterID;

    const condition = {};
    if(siteID){
      condition.siteID = siteID;
    }else{
      if(branchMasterID)
      condition.branchMasterID = branchMasterID;
    }
    if(fromDate && toDate) condition.expense_date = {
      [Op.between]: [fromDate, toDate]
    };

    const includedModels = [
        {
          // required: true,
          model: OfficeExpense,
          as: 'officeExpense',
          where: condition,
          include: [
            {
              model: BranchMaster,
              attributes: ['branchName', 'companyMasterID'],
            },
            {
              model: Site,
              attributes: ['siteName', 'companyMasterID'],
            },
            {
              model: UserMaster,
              as: 'createdBy',
              attributes: ['displayName']
            }
          ]
        },
        {
          model: OfficeExpenseHead,
          attributes: ['officeExpenseHeadID', 'officeExpenseHead', 'officeExpenseCategoryID'],
          include: [
            {
              model: OfficeExpenseCategory,
              attributes: ['officeExpenseCategory']
            }
          ]
        }
      ]

    if (exportData) {

      const batchSize = 5000; // Reduce to control memory usage
      let offset = 0;
      let hasMore = true;
      let rowCount = 0;

      const exportDir = path.join(__dirname, '../uploads/Office-expense-report');
      if (!fs.existsSync(exportDir)) {
        fs.mkdirSync(exportDir, { recursive: true });
      }

      const fileName = `${companyMasterID}_Office_Expense_Report_${Date.now()}.xlsx`;
      const filePath = path.join(exportDir, fileName);

      const workbook = new Excel.stream.xlsx.WorkbookWriter({
        filename: filePath,
      });
      const worksheet = workbook.addWorksheet('Office Expense Report');

      const headerRow = worksheet.addRow([
        'Branch Name',
        'Site Name',
        'Expense Date',
        'Expense Category',
        'Expense Head',
        'Amount',
        'Description',
        'Office Expense Status',
        'Applied By',
      ]);

      formatFirstRow(worksheet, 1);

      headerRow.commit(); // ✅ Now it's safe

      while (hasMore) {
        const batchRows = await OfficeExpenseTransaction.findAll({
        offset: paginationQuery.offset,
        limit: batchSize,
        where: {
          status: {
            [Op.ne]: 10
          }
        },
        include: includedModels,
        order: [[Sequelize.literal(`"officeExpense.expense_date"`), 'DESC']]
      })

      hasMore = batchRows.length === batchSize;
        offset += batchSize;

        if (batchRows.length === 0 && rowCount === 0) {
          console.error('❌ No data found to generate the file!');
          return res.status(statusCodes.OK).json({
            status: 401,
            message: '❌ No data found to generate the file!'
          })
        }

        for(let [index, row] of batchRows.entries()){
          let authorizationStatus = 'Pending';
          if (+row.authorizationStatus == 3) {
            authorizationStatus = 'Approved';
            if (row.erpJvid || row.payment_Id) {
              authorizationStatus = 'Paid';
            }
          } else if (+row.authorizationStatus == 4) {
            authorizationStatus = 'Rejected';
          }
          
          try {
          const rowData = [
            row?.officeExpense?.branchMaster?.branchName || '',
            row?.officeExpense?.site?.siteName || '',
            moment(row?.officeExpense?.expense_date, 'YYYY-MM-DD').format('DD-MM-YYYY') || '',
            row?.officeExpenseHead?.officeExpenseCategory?.officeExpenseCategory,
            row?.officeExpenseHead?.officeExpenseHead,
            row?.expenseAmount,
            row?.description,
            authorizationStatus,
            row?.officeExpense?.createdBy?.displayName
          ]

          worksheet.addRow(rowData).commit();
          rowCount++;
        } catch (error) {
          console.error(`⚠️ Error writing row ${index} of batch:`, err);
        }
      }
        
      }

      await workbook.commit();
      res.download(filePath, fileName, (err) => {
        if (err) {
          console.error('❌ Error sending file to client:', err);
          return res.status(500).send('Error sending file');
        }

        // Optional: Delete file after download
        fs.unlink(filePath, (unlinkErr) => {
          if (unlinkErr) {
            console.error('⚠️ Failed to delete file:', unlinkErr);
          } else {
            console.log('🗑️ File deleted successfully after download.');
          }
        });
      });

    } else {
      const { rows,  count } = await OfficeExpenseTransaction.findAndCountAll({
        // separate: true,
        ...paginationQuery,
        where: {
          status: {
            [Op.ne]: 10
          },
          [Op.or]: [
            {
              '$officeExpense.site.companyMasterID$': companyMasterID,
            },
            {
              '$officeExpense.branchMaster.companyMasterID$': companyMasterID
            }
          ]
        },
        include: includedModels,
        order: [[Sequelize.literal(`"officeExpense.expense_date"`), 'DESC']]
      })

      const formattedData = rows.map((row) => ({
          branch: row?.officeExpense?.branchMaster?.branchName || '',
          site: row?.officeExpense?.site?.siteName || '',
          expense_date: moment(row?.officeExpense?.expense_date, 'YYYY-MM-DD').format('DD-MM-YYYY') || '',
          officeExpenseCategory: row?.officeExpenseHead?.officeExpenseCategory?.officeExpenseCategory,
          officeExpenseHead: row?.officeExpenseHead?.officeExpenseHead,
          expenseAmount: row?.expenseAmount,
          description: row?.description,
          authorizationStatus: row?.authorizationStatus,
          appliedBy: row?.officeExpense?.createdBy?.displayName 
      }))

      return res.status(statusCodes.OK).json({
        status: statusCodes.OK,
        data: formattedData,
        totalcount: count
      })
    } 
  } catch (error) {
    next(error);
  }
}